  insert into public.t3a_d1_branch_rule(dimension_id, rule_code, rule_condition, rule_effect, rule_order) values ('D9','BR-D9-05','Q-D9-05 returns A1','Q-D9-05b served. Which open points exists only once a question about a listed open point was stated',5);
  insert into public.t3a_d1_branch_rule(dimension_id, rule_code, rule_condition, rule_effect, rule_order) values ('D9','BR-D9-06','Q-D9-06 returns A1','Q-D9-06b served. Which trial steps exists only once a listed trial step was stated',6);
  insert into public.t3a_d1_branch_rule(dimension_id, rule_code, rule_condition, rule_effect, rule_order) values ('D9','BR-D9-07','Q-D9-07 returns A1, A2','Q-D9-07b served. Which work exists once work ahead was named, whether or not a point was stated',7);
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('T3A-D9-EXEC-001-CONSTRUCT', 'construct'::public.t3a_content_family, 'D9 construct', 'D9', 'not_applicable'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_applicable'::public.t3a_operational_state, '{"situation_classes": {"SC-D9-1": {"situation": "Feedback on the participant''s work has been given, by one party or by several", "pattern_family": "IPF-D9-01"}, "SC-D9-2": {"situation": "A result, test or check has shown that the current approach is not producing what the work needs", "pattern_family": "IPF-D9-02"}, "SC-D9-3": {"situation": "A tool, system, rule or procedure the participant has not used before is now required for the work", "pattern_family": "IPF-D9-03"}, "SC-D9-4": {"situation": "The participant has been placed in work outside the work they have done before", "pattern_family": "IPF-D9-04"}, "SC-D9-5": {"situation": "Another person''s method for the work is available to the participant", "pattern_family": "IPF-D9-05"}, "SC-D9-6": {"situation": "The knowledge the work depends on is undocumented or held only by other people", "pattern_family": "IPF-D9-06"}, "SC-D9-7": {"situation": "An approach the participant already uses has been challenged, and the situation records grounds for keeping it as well as for changing it", "pattern_family": "IPF-D9-07"}}, "conduct_elements": {"CE-D9-01": {"name": "What the situation showed, named", "supports": "Which of the indications the source sets out the participant named. The indications are listed by the source, so the selection is bounded and never judged", "does_not_support": "Any claim about insight, perception or understanding, and any claim that the participant saw what others missed"}, "CE-D9-02": {"name": "Change to the approach stated", "supports": "Which of the changes to the approach the source makes available the participant stated", "does_not_support": "Any claim that the change was right, made, adopted or effective, and any claim that stating a change is preferable to keeping the approach"}, "CE-D9-03": {"name": "Approach kept, with the ground stated", "supports": "Whether the participant stated that all or part of the current approach is to be kept, and which of the grounds the source records they named for it", "does_not_support": "Any claim about conviction, stubbornness or independence of mind, and any claim that keeping the approach is preferable to changing it"}, "CE-D9-04": {"name": "Source of knowledge stated as one to go to", "supports": "Which of the sources of knowledge the source makes available the participant stated as one to go to: people, documentation, records, tools or courses", "does_not_support": "Any claim about self reliance or its absence, and any inference from stating none"}, "CE-D9-05": {"name": "Question stated", "supports": "Which of the open points the source sets out the participant stated a question about", "does_not_support": "Any claim about curiosity or its absence, and any judgment of the question''s quality"}, "CE-D9-06": {"name": "Trial step stated", "supports": "Which of the trial steps the source makes available the participant stated before adopting a change in full: a small part first, a parallel run, a check against a known case", "does_not_support": "Any claim about caution or hesitation, and any claim that a trial was carried out"}, "CE-D9-07": {"name": "Work ahead named", "supports": "What work ahead the participant named the stated approach as applying to, and whether a point at which it applies was stated. This is the observable limit of a single observation: the next step, not later conduct", "does_not_support": "Any prediction that the approach will be applied, and any claim that learning occurred"}, "CE-D9-08": {"name": "Record of the approach stated", "supports": "Whether the participant stated that the approach is to be recorded, and where", "does_not_support": "Any claim about diligence or thoroughness"}, "CE-D9-09": {"name": "Statement when an earlier statement was put back", "supports": "What the participant stated when the source''s account test put an earlier statement back to them, against what the situation records", "does_not_support": "Any claim about consistency, defensiveness or self awareness"}}, "coverage": {"CE-D9-01": ["Carried", "Carried", "Carried", "Carried"], "CE-D9-02": ["Carried", "Carried", "Carried", "Carried"], "CE-D9-03": ["Carried", "Carried", "Carried", "Carried"], "CE-D9-04": ["Carried", "Carried", "Carried", "Carried"], "CE-D9-05": ["Carried", "Carried", "Carried", "Carried"], "CE-D9-06": ["Carried", "Carried", "Carried", "Carried"], "CE-D9-07": ["Carried", "Carried", "Carried", "Carried"], "CE-D9-08": ["Carried", "Carried", "Carried", "Carried"], "CE-D9-09": ["Carried", "Carried", "NOT IN LAUNCH DESIGN", "Carried"]}, "source_fields": {"permitted_administration_variance": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The administration variance the source permits, recorded wherever it occurs"}, "unsupported_inferences": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The inferences the source must never support"}, "compatibility_class": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The delivery form class of the source, derived from its Stage"}, "situation_shown": {"type": "text", "stages": "1, 2, 3, 4", "holds": "Where the participant meets what the situation shows. It is always about the work or a method, never about the participant''s capacity, age, origin, language or education"}, "current_approach": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The approach to the work the source establishes as the participant''s when the situation begins"}, "indications": {"type": "list: IN, mapped", "stages": "1, 2, 3, 4", "holds": "What the situation shows about the work or a method, each quoted in the material map; consumed by Q-D9-01b"}, "approach_changes": {"type": "list: AC", "stages": "1, 2, 3, 4", "holds": "The changes to the approach the source makes available; consumed by Q-D9-02b. Each is a change to how the work is done, never a change in the participant"}, "retention_grounds": {"type": "list: RG, mapped", "stages": "1, 2, 3, 4", "holds": "The grounds the source records for keeping all or part of the current approach, each quoted in the material map; consumed by Q-D9-03b. Every D9 source records at least one"}, "knowledge_sources": {"type": "list: KS", "stages": "1, 2, 3, 4", "holds": "The sources of knowledge the source makes available: people, documentation, records, tools or courses; consumed by Q-D9-04b"}, "open_points": {"type": "list: OP", "stages": "1, 2, 3, 4", "holds": "The points the source leaves open that a question could address; consumed by Q-D9-05b"}, "trial_steps": {"type": "list: TS", "stages": "1, 2, 3, 4", "holds": "The ways the source makes available to try a change on a part of the work, or check it against a known case, before adopting it in full; consumed by Q-D9-06b. May be Empty"}, "next_work": {"type": "list: NW", "stages": "1, 2, 3, 4", "holds": "The work ahead the source establishes, to which a stated approach could apply; consumed by Q-D9-07b"}, "record_place": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The place a record of the approach could be made, or None"}, "practice_origin": {"type": "text", "stages": "1, 2, 3, 4", "holds": "Where the source places any practice the participant brought from another employer, country, training or culture, or None. Retained for source truth; never rendered, never on the mentor reference card, never the subject of any entry"}, "account_test_point": {"type": "point: Account test", "stages": "1, 2, 4", "holds": "The reveal or beat at which an earlier statement is put back to the participant, or None"}, "account_test_record": {"type": "text", "stages": "1, 2, 4", "holds": "What the situation records on the point the account test puts back, which is the reference for entries ST-D9-041 and ST-D9-042, or None"}, "list_note": {"type": "text", "stages": "1, 2, 3, 4", "holds": "Why a list is empty, and any item withheld from a list as not offered, or None"}, "source_note": {"type": "text", "stages": "1, 2, 3, 4", "holds": "A shared Stage 3 submission, a re-framing, a referral or other situation context the source carries, or None"}, "situation_class_label": {"type": "text", "stages": "1, 2, 3, 4", "holds": "One approved generic phrase naming the kind of situation; never the source title or scenario detail"}, "observation_mode_label": {"type": "enum: written_response, structured_live_session, work_sample, group_session", "stages": "1, 2, 3, 4", "holds": "The observation mode of the Stage at which the source is served"}}, "source": "T3A-D9-EXEC-001 v1.1"}'::jsonb from public.t3a_content_object where identifier = 'T3A-D9-EXEC-001-CONSTRUCT' and family = 'construct'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('T3A-D9-EXEC-001-DETERMINATION', 'determination_question_set'::public.t3a_content_family, 'D9 determination set', 'D9', 'not_applicable'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_applicable'::public.t3a_operational_state, '{"questions": {"Q-D9-01": {"element": "CE-D9-01", "capture_set": "C1", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D9-01b": {"element": "CE-D9-01", "capture_set": "C1b", "answer_type": "Bound selection, one or more", "source_bound_to": "indications", "served_when": "C1 records an indication the source sets out named"}, "Q-D9-02": {"element": "CE-D9-02", "capture_set": "C2", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D9-02b": {"element": "CE-D9-02", "capture_set": "C2b", "answer_type": "Bound selection, one or more", "source_bound_to": "approach_changes", "served_when": "C2 records a change to the approach the source makes available"}, "Q-D9-03": {"element": "CE-D9-03", "capture_set": "C3", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play. Every D9 source records retention grounds"}, "Q-D9-03b": {"element": "CE-D9-03", "capture_set": "C3b", "answer_type": "Bound selection, one or more", "source_bound_to": "retention_grounds", "served_when": "C3 records a ground the source sets out named"}, "Q-D9-04": {"element": "CE-D9-04", "capture_set": "C4", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D9-04b": {"element": "CE-D9-04", "capture_set": "C4b", "answer_type": "Bound selection, one or more", "source_bound_to": "knowledge_sources", "served_when": "C4 records a source of knowledge the source makes available"}, "Q-D9-05": {"element": "CE-D9-05", "capture_set": "C5", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D9-05b": {"element": "CE-D9-05", "capture_set": "C5b", "answer_type": "Bound selection, one or more", "source_bound_to": "open_points", "served_when": "C5 records a question about an open point the source sets out"}, "Q-D9-06": {"element": "CE-D9-06", "capture_set": "C6", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source lists trial steps"}, "Q-D9-06b": {"element": "CE-D9-06", "capture_set": "C6b", "answer_type": "Bound selection, one or more", "source_bound_to": "trial_steps", "served_when": "C6 records a trial step the source makes available"}, "Q-D9-07": {"element": "CE-D9-07", "capture_set": "C7", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D9-07b": {"element": "CE-D9-07", "capture_set": "C7b", "answer_type": "Bound selection, one or more", "source_bound_to": "next_work", "served_when": "C7 records work ahead named"}, "Q-D9-08": {"element": "CE-D9-08", "capture_set": "C8", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D9-09": {"element": "CE-D9-09", "capture_set": "C9", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries account_test_point"}}, "capture_sets": {"C1": {"title": "Which indications of what the situation showed the participant named", "lines": ["Named one or more of the indications the source sets out.", "Named an indication the source does not set out.", "Named no indication during the observation."], "bound": null, "type": "content", "whole_session": "Named no indication during the observation."}, "C1b": {"title": "Which listed indications were named", "lines": ["LISTED Selected each indication named.", "LISTED + NAMED_UNLISTED_INDICATION Selected the indications named and an indication outside the list."], "bound": {"field": "indications", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C2": {"title": "Which change to the approach the participant stated", "lines": ["Stated a change to the approach from those the source makes available.", "Stated a change to the approach the source does not make available.", "Stated no change to the approach during the observation."], "bound": null, "type": "content", "whole_session": "Stated no change to the approach during the observation."}, "C2b": {"title": "Which listed changes to the approach were stated", "lines": ["LISTED Selected each listed change to the approach stated.", "LISTED + STATED_UNLISTED_CHANGE Selected the listed changes to the approach stated and a change outside the list."], "bound": {"field": "approach_changes", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C3": {"title": "What the participant stated about keeping the current approach", "lines": ["Stated that all or part of the current approach is to be kept and named a ground the source sets out.", "Stated that all or part of the current approach is to be kept and named a ground the source does not set out.", "Stated that all or part of the current approach is to be kept and named no ground.", "Stated nothing about keeping the current approach during the observation."], "bound": null, "type": "content", "whole_session": "Stated nothing about keeping the current approach during the observation."}, "C3b": {"title": "Which listed grounds were named", "lines": ["LISTED Selected each listed ground named.", "LISTED + NAMED_UNLISTED_GROUND Selected the listed grounds named and a ground outside the list."], "bound": {"field": "retention_grounds", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C4": {"title": "Which source of knowledge the participant stated as one to go to", "lines": ["Stated a source of knowledge to go to from those the source makes available.", "Stated a source of knowledge to go to that the source does not make available.", "Stated no source of knowledge to go to during the observation."], "bound": null, "type": "content", "whole_session": "Stated no source of knowledge to go to during the observation."}, "C4b": {"title": "Which listed sources of knowledge were stated", "lines": ["LISTED Selected each listed source of knowledge stated.", "LISTED + STATED_UNLISTED_SOURCE Selected the listed sources of knowledge stated and a source of knowledge outside the list."], "bound": {"field": "knowledge_sources", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C5": {"title": "Which open point the participant stated a question about", "lines": ["Stated a question about one or more of the open points the source sets out.", "Stated a question about a point the source does not set out.", "Stated no question during the observation."], "bound": null, "type": "content", "whole_session": "Stated no question during the observation."}, "C5b": {"title": "Which open points a question was stated about", "lines": ["LISTED Selected each open point a question was stated about.", "LISTED + QUESTIONED_UNLISTED_POINT Selected the open points a question was stated about and a point outside the list."], "bound": {"field": "open_points", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C6": {"title": "Which trial step the participant stated before adopting a change in full", "lines": ["Stated a trial step from those the source makes available.", "Stated a trial step the source does not make available.", "Stated no trial step during the observation."], "bound": null, "type": "content", "whole_session": "Stated no trial step during the observation."}, "C6b": {"title": "Which listed trial steps were stated", "lines": ["LISTED Selected each listed trial step stated.", "LISTED + STATED_UNLISTED_TRIAL Selected the listed trial steps stated and a trial step outside the list."], "bound": {"field": "trial_steps", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C7": {"title": "What work ahead the participant named the stated approach as applying to, and from when", "lines": ["Named work ahead the stated approach applies to and stated when it applies.", "Named work ahead the stated approach applies to and stated no point at which it applies.", "Stated that the approach applies to work ahead and named none.", "Stated nothing about work ahead during the observation."], "bound": null, "type": "content", "whole_session": "Stated nothing about work ahead during the observation."}, "C7b": {"title": "Which items of work ahead were named", "lines": ["LISTED Selected each item of work ahead named.", "LISTED + NAMED_UNLISTED_WORK Selected the items of work ahead named and an item of work outside the list."], "bound": {"field": "next_work", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C8": {"title": "Whether a record of the approach was stated, and where", "lines": ["Stated that the approach is to be recorded and named where.", "Stated that the approach is to be recorded and named no place for it.", "Stated no record during the observation."], "bound": null, "type": "content", "whole_session": "Stated no record during the observation."}, "C9": {"title": "What was stated when an earlier statement was put back to the participant", "lines": ["Stated content that corresponds to what the source records.", "Stated content that differs from what the source records.", "Stated that what was put back was not what they had said.", "Stated nothing about what was put back during the observation."], "bound": null, "type": "content", "whole_session": "Stated nothing about what was put back during the observation."}}, "branch_rules": {"BR-D9-01": {"child": "Q-D9-01b", "parent": "Q-D9-01", "serving_answers": ["A1"], "note": "Which indications exists only once a listed indication was named"}, "BR-D9-02": {"child": "Q-D9-02b", "parent": "Q-D9-02", "serving_answers": ["A1"], "note": "Which changes exists only once a listed change to the approach was stated"}, "BR-D9-03": {"child": "Q-D9-03b", "parent": "Q-D9-03", "serving_answers": ["A1"], "note": "Which grounds exists only once a listed ground for keeping the approach was named"}, "BR-D9-04": {"child": "Q-D9-04b", "parent": "Q-D9-04", "serving_answers": ["A1"], "note": "Which sources of knowledge exists only once a listed source of knowledge was stated"}, "BR-D9-05": {"child": "Q-D9-05b", "parent": "Q-D9-05", "serving_answers": ["A1"], "note": "Which open points exists only once a question about a listed open point was stated"}, "BR-D9-06": {"child": "Q-D9-06b", "parent": "Q-D9-06", "serving_answers": ["A1"], "note": "Which trial steps exists only once a listed trial step was stated"}, "BR-D9-07": {"child": "Q-D9-07b", "parent": "Q-D9-07", "serving_answers": ["A1", "A2"], "note": "Which work exists once work ahead was named, whether or not a point was stated"}}, "source": "T3A-D9-EXEC-001 v1.1"}'::jsonb from public.t3a_content_object where identifier = 'T3A-D9-EXEC-001-DETERMINATION' and family = 'determination_question_set'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('T3A-D9-EXEC-001-STATEMENT-LIBRARY', 'statement_library'::public.t3a_content_family, 'D9 statement library', 'D9', 'not_applicable'::public.t3a_operational_state);
