  insert into public.t3a_d1_language_template(language_template_id, dimension_id, template_body, bound_variables, eligible_states, precedence) values ('L-D9-DIV-001','D9','The observations that follow differ. Each is recorded against its own context and neither is presented in preference to the other.','{}'::text[],'{}',4);
  insert into public.t3a_d1_language_template(language_template_id, dimension_id, template_body, bound_variables, eligible_states, precedence) values ('L-D9-ATT-001','D9','An earlier observation in this dimension recorded different conduct. Both remain in the record.','{}'::text[],'{}',5);
