  insert into public.t3a_d1_language_template(language_template_id, dimension_id, template_body, bound_variables, eligible_states, precedence) values ('L-D9-SINGLE-001','D9','The observations in this dimension were made by one authorized observer.','{}'::text[],'{}',10);
