  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S1-001', 'source'::public.t3a_content_family, 'THE RETURN DUE IN FIVE DAYS ON A NEW SYSTEM', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE RETURN DUE IN FIVE DAYS ON A NEW SYSTEM", "source_digest": "e83f12559c0abd9b466203d7b3fd743e40855c56e5a7ddf608a12a83f1ce87f9", "situation": "You are a junior accountant who joined an accounting firm two weeks ago. The firm prepares returns on its own tax preparation system, which you had not used before you joined. Your supervisor has given you your first client file to prepare on your own: a corporate tax return due in five business days. She has told you that the system has a built-in tutorial and that a colleague on the team has used it for three years.\n\nWhat the record shows: after two hours with the tutorial you can enter data, but the tutorial does not clearly cover how to link the depreciation schedule to the asset register, a step the corporate return needs; the colleague is at his desk and on a deadline of his own; the help forum has a thread from 2019 on the linking step that uses terms from an older release; the system''s small business deduction differs from your own manual calculation by $4,200; your manual calculation has matched the filed figures on every return you prepared before; the system''s review tool flags any schedule a return still needs; and your supervisor has asked for a progress note by the end of day three.", "reveals": [{"code": "R1", "text": "What does what you have found so far tell you about how to get the return done, and what do you do next?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you change in how you are doing this, and what do you keep as it is? Why?", "role": "Information"}, {"code": "R3", "text": "Who or what do you go to, and what do you ask?", "role": "Information"}, {"code": "R4", "text": "Before you rely fully on a different way of doing it, what, if anything, do you do first?", "role": "Information"}, {"code": "R5", "text": "Which work ahead does your approach apply to, and from when?", "role": "Information"}, {"code": "R6", "text": "What, if anything, gets written down, and where?", "role": "Information"}, {"code": "R7", "text": "On day three your supervisor writes: \"You said the tutorial covers the depreciation link. Does it?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out three indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists four sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out three open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists two trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out three items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the tutorial does not clearly cover the linking step the return needs", "Where the participant meets it": "The situation", "Quoted text": "the tutorial does not clearly cover how to link the depreciation schedule to the asset register"}, {"Item": "IN2", "Item text": "the system''s deduction differs from the manual calculation by $4,200", "Where the participant meets it": "The situation", "Quoted text": "differs from your own manual calculation by $4,200"}, {"Item": "IN3", "Item text": "the forum thread on the linking step uses terms from an older release", "Where the participant meets it": "The situation", "Quoted text": "uses terms from an older release"}, {"Item": "RG1", "Item text": "the manual calculation has matched the filed figures on every earlier return", "Where the participant meets it": "The situation", "Quoted text": "your manual calculation has matched the filed figures on every return you prepared before"}], "source_sheet": {"d9_situation_class": "SC-D9-3", "workplace_demand": "Preparing a client''s corporate return in five days on a tax system the participant had not used before.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "How long the participant takes to become familiar with the system; the colleague''s availability; the forum''s age.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the participant is a fast or slow learner of software; that keeping the manual calculation shows distrust or caution; anything about the participant''s education or prior firm.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "situation_shown": "In the situation: \"the tutorial does not clearly cover how to link the depreciation schedule to the asset register.\"", "current_approach": "Preparing returns with a manual calculation alongside, as at the previous firm, on a system new to the participant.", "indications": [{"id": "IN1", "text": "the tutorial does not clearly cover the linking step the return needs"}, {"id": "IN2", "text": "the system''s deduction differs from the manual calculation by $4,200"}, {"id": "IN3", "text": "the forum thread on the linking step uses terms from an older release"}], "approach_changes": [{"id": "AC1", "text": "work the linking step from the forum thread against the current screens"}, {"id": "AC2", "text": "prepare the deduction on the system and reconcile it line by line with the manual figure"}, {"id": "AC3", "text": "run the system''s review tool before the return goes to the supervisor"}], "retention_grounds": [{"id": "RG1", "text": "the manual calculation has matched the filed figures on every earlier return"}], "knowledge_sources": [{"id": "KS1", "text": "the colleague who has used the system for three years"}, {"id": "KS2", "text": "the system''s built-in tutorial"}, {"id": "KS3", "text": "the help forum thread from 2019"}, {"id": "KS4", "text": "the supervisor, at the day three progress note"}], "open_points": [{"id": "OP1", "text": "how the linking step works in the current release"}, {"id": "OP2", "text": "why the system''s deduction differs from the manual figure"}, {"id": "OP3", "text": "which schedules the return still needs"}], "trial_steps": [{"id": "TS1", "text": "work the linking step on one asset before linking the full register"}, {"id": "TS2", "text": "reconcile the deduction on the system against the manual figure before relying on either"}], "next_work": [{"id": "NW1", "text": "the remaining sections of this return"}, {"id": "NW2", "text": "the progress note at the end of day three"}, {"id": "NW3", "text": "the next return prepared on the system"}], "record_place": "The client file''s working notes.", "practice_origin": "The participant''s previous firm used a different tax platform.", "account_test_point": "R7", "account_test_record": "The situation records that the tutorial does not clearly cover the depreciation linking step.", "list_note": null, "source_note": null, "situation_class_label": "A tool or system not used before, now required for the work", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D9-S1-001", "stage_code": "S1", "source_version_hash": "e83f12559c0abd9b466203d7b3fd743e40855c56e5a7ddf608a12a83f1ce87f9", "serving_eligible": false, "verbatim": "You are a junior accountant who joined an accounting firm two weeks ago. The firm prepares returns on its own tax preparation system, which you had not used before you joined. Your supervisor has given you your first client file to prepare on your own: a corporate tax return due in five business days. She has told you that the system has a built-in tutorial and that a colleague on the team has used it for three years.\n\nWhat the record shows: after two hours with the tutorial you can enter data, but the tutorial does not clearly cover how to link the depreciation schedule to the asset register, a step the corporate return needs; the colleague is at his desk and on a deadline of his own; the help forum has a thread from 2019 on the linking step that uses terms from an older release; the system''s small business deduction differs from your own manual calculation by $4,200; your manual calculation has matched the filed figures on every return you prepared before; the system''s review tool flags any schedule a return still needs; and your supervisor has asked for a progress note by the end of day three."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S1-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S1-002', 'source'::public.t3a_content_family, 'SEVEN ITEMS DOWN TO FOUR, AND THE CLIENT WANTS THEM BACK', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "SEVEN ITEMS DOWN TO FOUR, AND THE CLIENT WANTS THEM BACK", "source_digest": "6599c0f8a68dd5f0364942e766a8dd79de35523d34bc6a4c260ebf87c6267313", "situation": "You are a user experience designer at a design agency building a banking app for a corporate client. Last week your design director reviewed your prototype and asked you to reduce the home menu from seven items to four. You made that change. Today the client''s product manager reviewed the simplified version and asked for the account alerts and transfer shortcuts to be put back on the home screen.\n\nWhat the record shows: the design director''s note says the seven item menu tested as cluttered in the agency''s last two banking projects; the product manager''s note says account alerts and transfers are the two features their users open most, from the client''s own usage data; the usage data has been offered but not yet sent; the four item menu has not been tested with users; the agency''s prototype tool can show two versions side by side to a small user panel; and the client call is tomorrow at ten with both of them on it.", "reveals": [{"code": "R1", "text": "What does the feedback from the two of them tell you about the design, and what do you do in the next twenty four hours?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you change in how you are doing this, and what do you keep as it is? Why?", "role": "Information"}, {"code": "R3", "text": "Who or what do you go to, and what do you ask?", "role": "Information"}, {"code": "R4", "text": "Before you rely fully on a different way of doing it, what, if anything, do you do first?", "role": "Information"}, {"code": "R5", "text": "Which work ahead does your approach apply to, and from when?", "role": "Information"}, {"code": "R6", "text": "What, if anything, gets written down, and where?", "role": "Information"}, {"code": "R7", "text": "On the call the product manager says: \"You told us yesterday the four item menu was tested with users. Was it?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out three indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists four sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out three open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists two trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the seven item menu tested as cluttered in two earlier banking projects", "Where the participant meets it": "The situation", "Quoted text": "the seven item menu tested as cluttered in the agency''s last two banking projects"}, {"Item": "IN2", "Item text": "alerts and transfers are the two features the client''s users open most", "Where the participant meets it": "The situation", "Quoted text": "account alerts and transfers are the two features their users open most"}, {"Item": "IN3", "Item text": "the four item menu has not been tested with users", "Where the participant meets it": "The situation", "Quoted text": "the four item menu has not been tested with users"}, {"Item": "RG1", "Item text": "the seven item menu tested as cluttered in earlier projects", "Where the participant meets it": "The situation", "Quoted text": "the seven item menu tested as cluttered in the agency''s last two banking projects"}], "source_sheet": {"d9_situation_class": "SC-D9-1", "workplace_demand": "Revising a banking app home screen after conflicting feedback from the design director and the client.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "Which of the two reviewers is senior; how the call goes; the client relationship.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the participant gives way too easily or holds on too long; any comparison of the two reviewers'' judgment; anything about the participant''s design ability.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "situation_shown": "In the situation: \"asked for the account alerts and transfer shortcuts to be put back on the home screen.\"", "current_approach": "The four item home menu the participant built on the design director''s instruction.", "indications": [{"id": "IN1", "text": "the seven item menu tested as cluttered in two earlier banking projects"}, {"id": "IN2", "text": "alerts and transfers are the two features the client''s users open most"}, {"id": "IN3", "text": "the four item menu has not been tested with users"}], "approach_changes": [{"id": "AC1", "text": "place account alerts and transfers as shortcuts below the four item menu"}, {"id": "AC2", "text": "ask the client to send the usage data before the call"}, {"id": "AC3", "text": "show two versions side by side on the call"}], "retention_grounds": [{"id": "RG1", "text": "the seven item menu tested as cluttered in earlier projects"}], "knowledge_sources": [{"id": "KS1", "text": "the client''s usage data"}, {"id": "KS2", "text": "the design director"}, {"id": "KS3", "text": "the results from the agency''s last two banking projects"}, {"id": "KS4", "text": "the prototype tool''s side by side view"}], "open_points": [{"id": "OP1", "text": "what the client''s usage data shows for the other home features"}, {"id": "OP2", "text": "which of the two versions a small user panel completes faster"}, {"id": "OP3", "text": "whether the shortcuts can sit outside the main menu"}], "trial_steps": [{"id": "TS1", "text": "show both versions to a small user panel before the design is settled"}, {"id": "TS2", "text": "test the shortcut placement on one screen before reworking the rest"}], "next_work": [{"id": "NW1", "text": "tomorrow''s client call"}, {"id": "NW2", "text": "the next round of the banking app prototype"}], "record_place": "The project''s design decision log.", "practice_origin": null, "account_test_point": "R7", "account_test_record": "The situation records that the four item menu has not been tested with users.", "list_note": null, "source_note": null, "situation_class_label": "Feedback on the participant''s work, given by more than one party", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D9-S1-002", "stage_code": "S1", "source_version_hash": "6599c0f8a68dd5f0364942e766a8dd79de35523d34bc6a4c260ebf87c6267313", "serving_eligible": false, "verbatim": "You are a user experience designer at a design agency building a banking app for a corporate client. Last week your design director reviewed your prototype and asked you to reduce the home menu from seven items to four. You made that change. Today the client''s product manager reviewed the simplified version and asked for the account alerts and transfer shortcuts to be put back on the home screen.\n\nWhat the record shows: the design director''s note says the seven item menu tested as cluttered in the agency''s last two banking projects; the product manager''s note says account alerts and transfers are the two features their users open most, from the client''s own usage data; the usage data has been offered but not yet sent; the four item menu has not been tested with users; the agency''s prototype tool can show two versions side by side to a small user panel; and the client call is tomorrow at ten with both of them on it."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S1-002' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S1-003', 'source'::public.t3a_content_family, 'THE WRISTBAND CHECK ON THE SHADOW SHIFT', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE WRISTBAND CHECK ON THE SHADOW SHIFT", "source_digest": "90002fb155958845509ebbc86d8fe41088d9e0b460a3b2fb324e38aea8ba39ae", "situation": "You are a registered nurse in your first week on a medical surgical floor at a regional hospital. Today is your shadow shift with an experienced nurse on the floor. You observe and assist; you are not yet managing patients alone. The charge nurse has asked you to watch closely and to ask questions.\n\nWhat the record shows: the nurse you are shadowing checks each patient''s wristband and scans the medications, but does not ask the patient to state their name and date of birth; at the hospital where you worked before, a spoken check of name and date of birth was required before every medication; this floor''s medication policy binder is at the nursing station; the charge nurse is on the floor all shift; during a rapid response this morning you could not locate the crash cart, and the floor layout chart is posted by the elevators; and next week you manage your own patients.", "reveals": [{"code": "R1", "text": "What does what you have seen this morning tell you about how medications are given on this floor, and what do you do next?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you change in how you are doing this, and what do you keep as it is? Why?", "role": "Information"}, {"code": "R3", "text": "Who or what do you go to, and what do you ask?", "role": "Information"}, {"code": "R4", "text": "Before you rely fully on a different way of doing it, what, if anything, do you do first?", "role": "Information"}, {"code": "R5", "text": "Which work ahead does your approach apply to, and from when?", "role": "Information"}, {"code": "R6", "text": "What, if anything, gets written down, and where?", "role": "Information"}, {"code": "R7", "text": "At the end of the shift the charge nurse says: \"You said the floor''s policy only requires the wristband scan. Is that what the binder says?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists two changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists four sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the nurse being shadowed checks wristbands and scans medications without a spoken check", "Where the participant meets it": "The situation", "Quoted text": "does not ask the patient to state their name and date of birth"}, {"Item": "IN2", "Item text": "the participant could not locate the crash cart during the rapid response", "Where the participant meets it": "The situation", "Quoted text": "you could not locate the crash cart"}, {"Item": "RG1", "Item text": "a spoken check of name and date of birth was required at the previous hospital", "Where the participant meets it": "The situation", "Quoted text": "a spoken check of name and date of birth was required before every medication"}], "source_sheet": {"d9_situation_class": "SC-D9-5 with SC-D9-7", "workplace_demand": "Working out how medications are given on a new floor during a shadow shift, where practice differs from the participant''s previous hospital.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "Whether the experienced nurse is right; how the experienced nurse treats the participant; which hospital''s practice is better.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": "SENSITIVE_CONTENT", "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the practice of either hospital is better than the other; that raising or not raising the difference shows deference, confidence or its absence; anything about the participant''s training or origin.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "situation_shown": "In the situation: \"does not ask the patient to state their name and date of birth.\"", "current_approach": "The identification practice the participant brought from the hospital where they worked before.", "indications": [{"id": "IN1", "text": "the nurse being shadowed checks wristbands and scans medications without a spoken check"}, {"id": "IN2", "text": "the participant could not locate the crash cart during the rapid response"}], "approach_changes": [{"id": "AC1", "text": "read the floor''s medication policy before the next medication round"}, {"id": "AC2", "text": "walk the floor against the layout chart before the end of the shift"}], "retention_grounds": [{"id": "RG1", "text": "a spoken check of name and date of birth was required at the previous hospital"}], "knowledge_sources": [{"id": "KS1", "text": "the floor''s medication policy binder"}, {"id": "KS2", "text": "the charge nurse"}, {"id": "KS3", "text": "the floor layout chart by the elevators"}, {"id": "KS4", "text": "the nurse being shadowed"}], "open_points": [{"id": "OP1", "text": "which identification steps this floor''s policy requires"}, {"id": "OP2", "text": "where the crash cart and the emergency equipment are kept"}], "trial_steps": [{"id": "TS1", "text": "confirm the identification step against the binder before the next round"}], "next_work": [{"id": "NW1", "text": "the next medication round on this shift"}, {"id": "NW2", "text": "next week, when the participant manages their own patients"}], "record_place": "The participant''s orientation checklist.", "practice_origin": "The participant''s previous hospital required a spoken check of name and date of birth before every medication.", "account_test_point": "R7", "account_test_record": "The situation records that the floor''s medication policy binder is at the nursing station and has not yet been read by the participant.", "list_note": null, "source_note": null, "situation_class_label": "Another person''s method for the work available to the participant", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D9-S1-003", "stage_code": "S1", "source_version_hash": "90002fb155958845509ebbc86d8fe41088d9e0b460a3b2fb324e38aea8ba39ae", "serving_eligible": false, "verbatim": "You are a registered nurse in your first week on a medical surgical floor at a regional hospital. Today is your shadow shift with an experienced nurse on the floor. You observe and assist; you are not yet managing patients alone. The charge nurse has asked you to watch closely and to ask questions.\n\nWhat the record shows: the nurse you are shadowing checks each patient''s wristband and scans the medications, but does not ask the patient to state their name and date of birth; at the hospital where you worked before, a spoken check of name and date of birth was required before every medication; this floor''s medication policy binder is at the nursing station; the charge nurse is on the floor all shift; during a rapid response this morning you could not locate the crash cart, and the floor layout chart is posted by the elevators; and next week you manage your own patients."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S1-003' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S1-004', 'source'::public.t3a_content_family, 'A BRIEFING ON SOLAR IN FIVE DAYS', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "A BRIEFING ON SOLAR IN FIVE DAYS", "source_digest": "b43245c867ff3a4bb157e2449c1a0fff55901cb59d3c070e90368cebe64c2ea4", "situation": "You are a project coordinator at a regional utility that has run coal and natural gas plants. The utility has announced a ten year transition to solar and wind and the closure of two of its four coal plants within three years. Your projects for the past eight years have been coal plant maintenance. Your director has asked you to give the leadership team a fifteen minute briefing next week on the operational challenges of moving from coal to solar.\n\nWhat the record shows: a colleague who has been studying renewables offers to share her notes; an external consultant is available for one hour on day three; the utility''s planning team holds a draft workforce plan for the transition; your draft estimate of operators needed for a solar site was taken from a coal site staffing ratio; the leadership team asked for operational challenges, not a full technical account; and the briefing is on day five.", "reveals": [{"code": "R1", "text": "What does what you have found so far tell you about how to prepare the briefing, and what do you do first?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you change in how you are doing this, and what do you keep as it is? Why?", "role": "Information"}, {"code": "R3", "text": "Who or what do you go to, and what do you ask?", "role": "Information"}, {"code": "R4", "text": "Before you rely fully on a different way of doing it, what, if anything, do you do first?", "role": "Information"}, {"code": "R5", "text": "Which work ahead does your approach apply to, and from when?", "role": "Information"}, {"code": "R6", "text": "What, if anything, gets written down, and where?", "role": "Information"}, {"code": "R7", "text": "On day four your director writes: \"You told me the staffing estimate came from the consultant. Did it?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists four sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists two trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the draft staffing estimate was taken from a coal site ratio", "Where the participant meets it": "The situation", "Quoted text": "was taken from a coal site staffing ratio"}, {"Item": "IN2", "Item text": "the leadership team asked for operational challenges, not a full technical account", "Where the participant meets it": "The situation", "Quoted text": "asked for operational challenges, not a full technical account"}, {"Item": "RG1", "Item text": "the briefing asks for operational challenges, which the participant''s maintenance projects bear on", "Where the participant meets it": "The situation", "Quoted text": "operational challenges of moving from coal to solar"}], "source_sheet": {"d9_situation_class": "SC-D9-4", "workplace_demand": "Preparing a leadership briefing in five days on work outside the participant''s eight years of projects.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "How much the participant knows about solar; the merits of the transition; the leadership team''s view of it.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the participant''s background is a limit or an advantage; how much was understood; that using a colleague''s notes shows dependence.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "situation_shown": "In the situation: \"your draft estimate of operators needed for a solar site was taken from a coal site staffing ratio.\"", "current_approach": "Coordinating coal plant maintenance projects and estimating from coal plant staffing ratios.", "indications": [{"id": "IN1", "text": "the draft staffing estimate was taken from a coal site ratio"}, {"id": "IN2", "text": "the leadership team asked for operational challenges, not a full technical account"}], "approach_changes": [{"id": "AC1", "text": "replace the staffing estimate with one checked against the consultant"}, {"id": "AC2", "text": "set the scope to operational challenges and leave technical detail out"}, {"id": "AC3", "text": "build the briefing on the planning team''s draft workforce plan"}], "retention_grounds": [{"id": "RG1", "text": "the briefing asks for operational challenges, which the participant''s maintenance projects bear on"}], "knowledge_sources": [{"id": "KS1", "text": "the colleague''s notes on renewables"}, {"id": "KS2", "text": "the external consultant, for one hour on day three"}, {"id": "KS3", "text": "the planning team''s draft workforce plan"}, {"id": "KS4", "text": "the director"}], "open_points": [{"id": "OP1", "text": "what staffing a solar site of this size needs"}, {"id": "OP2", "text": "which operational challenges the leadership team most needs covered"}], "trial_steps": [{"id": "TS1", "text": "take the draft to the colleague before the consultant hour"}, {"id": "TS2", "text": "run the fifteen minutes once against the clock before day five"}], "next_work": [{"id": "NW1", "text": "the leadership briefing on day five"}, {"id": "NW2", "text": "the transition planning that follows the briefing"}], "record_place": "The briefing''s source notes.", "practice_origin": null, "account_test_point": "R7", "account_test_record": "The situation records that the staffing estimate was taken from a coal site staffing ratio.", "list_note": null, "source_note": null, "situation_class_label": "Work outside the work the participant has done before", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D9-S1-004", "stage_code": "S1", "source_version_hash": "b43245c867ff3a4bb157e2449c1a0fff55901cb59d3c070e90368cebe64c2ea4", "serving_eligible": false, "verbatim": "You are a project coordinator at a regional utility that has run coal and natural gas plants. The utility has announced a ten year transition to solar and wind and the closure of two of its four coal plants within three years. Your projects for the past eight years have been coal plant maintenance. Your director has asked you to give the leadership team a fifteen minute briefing next week on the operational challenges of moving from coal to solar.\n\nWhat the record shows: a colleague who has been studying renewables offers to share her notes; an external consultant is available for one hour on day three; the utility''s planning team holds a draft workforce plan for the transition; your draft estimate of operators needed for a solar site was taken from a coal site staffing ratio; the leadership team asked for operational challenges, not a full technical account; and the briefing is on day five."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S1-004' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S1-005', 'source'::public.t3a_content_family, 'THE MENTOR''S ADVICE AND THE PROGRAM''S APPROACH', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE MENTOR''S ADVICE AND THE PROGRAM''S APPROACH", "source_digest": "e1006c7d882556b0ad81618ffef0f7f0bee532408ef047e6a9d80bb9dfe348b2", "situation": "You are a team lead, promoted three months ago at a financial services company, and you meet a senior director every two weeks as your mentor in the company''s leadership development program. You joined the program to work on giving difficult feedback, managing a team member whose work is below standard, and running team meetings. In the last four sessions the mentor''s advice has been about whom to align with and how decisions are made at the company.\n\nWhat the record shows: on the team member whose work is below standard, the mentor has advised you to leave it until after the reorganization, since raising it now could cost you support; the program''s guide asks team leads to give specific feedback within two weeks of a concern and to record it; the team member''s last two reports came back from the client with errors; the program coordinator has asked each team lead how their mentorship is going, by Friday; and the program offers a feedback workshop next month.", "reveals": [{"code": "R1", "text": "What does the mentor''s advice so far tell you about the help you are getting, and what do you do with it?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you change in how you are doing this, and what do you keep as it is? Why?", "role": "Information"}, {"code": "R3", "text": "Who or what do you go to, and what do you ask?", "role": "Information"}, {"code": "R4", "text": "Before you rely fully on a different way of doing it, what, if anything, do you do first?", "role": "Information"}, {"code": "R5", "text": "Which work ahead does your approach apply to, and from when?", "role": "Information"}, {"code": "R6", "text": "What, if anything, gets written down, and where?", "role": "Information"}, {"code": "R7", "text": "The coordinator writes: \"You told me your mentor''s advice matches the program guide on feedback. Does it?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out three indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists four sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out three items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the mentor''s advice is to wait until after the reorganization", "Where the participant meets it": "The situation", "Quoted text": "leave it until after the reorganization"}, {"Item": "IN2", "Item text": "the program guide asks for specific feedback within two weeks of a concern", "Where the participant meets it": "The situation", "Quoted text": "give specific feedback within two weeks of a concern"}, {"Item": "IN3", "Item text": "the team member''s last two reports came back from the client with errors", "Where the participant meets it": "The situation", "Quoted text": "last two reports came back from the client with errors"}, {"Item": "RG1", "Item text": "the mentor''s advice records how decisions are made at the company", "Where the participant meets it": "The situation", "Quoted text": "how decisions are made at the company"}], "source_sheet": {"d9_situation_class": "SC-D9-1 with SC-D9-7", "workplace_demand": "Deciding what to do with a mentor''s advice that differs from the leadership program''s guide.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The mentor''s motives; company politics; whether the reorganization happens.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the participant is political or naive; any judgment of the mentor; that following or not following the advice shows independence or deference.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "situation_shown": "In the situation: \"the mentor has advised you to leave it until after the reorganization.\"", "current_approach": "Taking the mentor''s advice on alignment and holding back on the team member until after the reorganization.", "indications": [{"id": "IN1", "text": "the mentor''s advice is to wait until after the reorganization"}, {"id": "IN2", "text": "the program guide asks for specific feedback within two weeks of a concern"}, {"id": "IN3", "text": "the team member''s last two reports came back from the client with errors"}], "approach_changes": [{"id": "AC1", "text": "give the team member specific feedback within two weeks, as the program guide asks"}, {"id": "AC2", "text": "take the leadership topics to the mentor at the next session"}, {"id": "AC3", "text": "attend next month''s feedback workshop"}], "retention_grounds": [{"id": "RG1", "text": "the mentor''s advice records how decisions are made at the company"}], "knowledge_sources": [{"id": "KS1", "text": "the program guide"}, {"id": "KS2", "text": "the program coordinator"}, {"id": "KS3", "text": "the mentor"}, {"id": "KS4", "text": "next month''s feedback workshop"}], "open_points": [{"id": "OP1", "text": "what the mentor would do about the team member''s errors, in the program''s terms"}, {"id": "OP2", "text": "what the program expects when a mentor''s advice differs from its guide"}], "trial_steps": [{"id": "TS1", "text": "take one leadership topic to the next session and see what the mentor offers on it"}], "next_work": [{"id": "NW1", "text": "the feedback to the team member"}, {"id": "NW2", "text": "the next mentoring session"}, {"id": "NW3", "text": "the reply to the coordinator by Friday"}], "record_place": "The program''s development log.", "practice_origin": null, "account_test_point": "R7", "account_test_record": "The situation records that the program guide asks for specific feedback within two weeks of a concern.", "list_note": null, "source_note": null, "situation_class_label": "Feedback on the participant''s work, given by one party", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D9-S1-005", "stage_code": "S1", "source_version_hash": "e1006c7d882556b0ad81618ffef0f7f0bee532408ef047e6a9d80bb9dfe348b2", "serving_eligible": false, "verbatim": "You are a team lead, promoted three months ago at a financial services company, and you meet a senior director every two weeks as your mentor in the company''s leadership development program. You joined the program to work on giving difficult feedback, managing a team member whose work is below standard, and running team meetings. In the last four sessions the mentor''s advice has been about whom to align with and how decisions are made at the company.\n\nWhat the record shows: on the team member whose work is below standard, the mentor has advised you to leave it until after the reorganization, since raising it now could cost you support; the program''s guide asks team leads to give specific feedback within two weeks of a concern and to record it; the team member''s last two reports came back from the client with errors; the program coordinator has asked each team lead how their mentorship is going, by Friday; and the program offers a feedback workshop next month."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S1-005' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S1-006', 'source'::public.t3a_content_family, 'ROTATED TO PAINT AND COATINGS ON MONDAY', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "ROTATED TO PAINT AND COATINGS ON MONDAY", "source_digest": "9574706d44a42696d75ee384c169299e8033dd3e1632c168ef29e85ea7bbf72c", "situation": "You are a production supervisor at an automotive parts plant. For four years you have run the machining department. The plant manager has rotated supervisors between departments, and from Monday you run paint and coatings, where you have not worked before. The department has twenty two operators and a reject rate of eight percent, twice the plant average.\n\nWhat the record shows: the lead operator, who has worked in the department for fifteen years, tells you the last rotated supervisor made decisions without asking and the floor spent three months correcting them; Friday''s spray booth temperature log shows the booth above its specified range for two hours; the lead operator says the rejects follow the drying cycle the previous supervisor shortened; the plant''s quality engineer holds reject data by shift; the coating supplier offers a technical visit within the week; four hundred parts are due for coating on Monday; and your machining practice of reviewing the process log at the start of every shift is in the plant''s supervisor standard.", "reveals": [{"code": "R1", "text": "What does what you have found on your first day tell you about the work, and what do you do first?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you change in how you are doing this, and what do you keep as it is? Why?", "role": "Information"}, {"code": "R3", "text": "Who or what do you go to, and what do you ask?", "role": "Information"}, {"code": "R4", "text": "Before you rely fully on a different way of doing it, what, if anything, do you do first?", "role": "Information"}, {"code": "R5", "text": "Which work ahead does your approach apply to, and from when?", "role": "Information"}, {"code": "R6", "text": "What, if anything, gets written down, and where?", "role": "Information"}, {"code": "R7", "text": "On Wednesday the plant manager says: \"You told me the rejects came from the operators. Is that what the floor told you?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out three indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists four sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the spray booth ran above its specified range for two hours on Friday", "Where the participant meets it": "The situation", "Quoted text": "above its specified range for two hours"}, {"Item": "IN2", "Item text": "the lead operator says the rejects follow the shortened drying cycle", "Where the participant meets it": "The situation", "Quoted text": "the rejects follow the drying cycle the previous supervisor shortened"}, {"Item": "IN3", "Item text": "the last rotated supervisor''s decisions took three months to correct", "Where the participant meets it": "The situation", "Quoted text": "the floor spent three months correcting them"}, {"Item": "RG1", "Item text": "reviewing the process log at the start of every shift is in the supervisor standard", "Where the participant meets it": "The situation", "Quoted text": "reviewing the process log at the start of every shift is in the plant''s supervisor standard"}], "source_sheet": {"d9_situation_class": "SC-D9-4", "workplace_demand": "Starting as supervisor of a department whose work is new to the participant, with a high reject rate.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The rotation decision itself, which is D6 context; the previous supervisor; the operators'' view of rotated supervisors.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "How much the participant knows about coatings; that taking the lead operator''s account shows humility or dependence; any comparison with the previous supervisor.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "situation_shown": "In the situation: \"the rejects follow the drying cycle the previous supervisor shortened.\"", "current_approach": "The machining department''s practice of reviewing the process log at the start of each shift.", "indications": [{"id": "IN1", "text": "the spray booth ran above its specified range for two hours on Friday"}, {"id": "IN2", "text": "the lead operator says the rejects follow the shortened drying cycle"}, {"id": "IN3", "text": "the last rotated supervisor''s decisions took three months to correct"}], "approach_changes": [{"id": "AC1", "text": "restore the drying cycle to its specified time"}, {"id": "AC2", "text": "review the reject data by shift with the quality engineer"}, {"id": "AC3", "text": "take the coating supplier''s technical visit"}], "retention_grounds": [{"id": "RG1", "text": "reviewing the process log at the start of every shift is in the supervisor standard"}], "knowledge_sources": [{"id": "KS1", "text": "the lead operator"}, {"id": "KS2", "text": "the quality engineer''s reject data by shift"}, {"id": "KS3", "text": "the coating supplier''s technical visit"}, {"id": "KS4", "text": "the spray booth temperature log"}], "open_points": [{"id": "OP1", "text": "why the drying cycle was shortened"}, {"id": "OP2", "text": "what the booth''s specified temperature range is for each coating"}], "trial_steps": [{"id": "TS1", "text": "run one batch on the specified drying cycle and compare its reject rate before changing every line"}], "next_work": [{"id": "NW1", "text": "Monday''s four hundred parts"}, {"id": "NW2", "text": "the department''s reject rate review with the plant manager"}], "record_place": "The department''s process change log.", "practice_origin": null, "account_test_point": "R7", "account_test_record": "The situation records that the lead operator says the rejects follow the drying cycle the previous supervisor shortened.", "list_note": null, "source_note": null, "situation_class_label": "Work outside the work the participant has done before", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D9-S1-006", "stage_code": "S1", "source_version_hash": "9574706d44a42696d75ee384c169299e8033dd3e1632c168ef29e85ea7bbf72c", "serving_eligible": false, "verbatim": "You are a production supervisor at an automotive parts plant. For four years you have run the machining department. The plant manager has rotated supervisors between departments, and from Monday you run paint and coatings, where you have not worked before. The department has twenty two operators and a reject rate of eight percent, twice the plant average.\n\nWhat the record shows: the lead operator, who has worked in the department for fifteen years, tells you the last rotated supervisor made decisions without asking and the floor spent three months correcting them; Friday''s spray booth temperature log shows the booth above its specified range for two hours; the lead operator says the rejects follow the drying cycle the previous supervisor shortened; the plant''s quality engineer holds reject data by shift; the coating supplier offers a technical visit within the week; four hundred parts are due for coating on Monday; and your machining practice of reviewing the process log at the start of every shift is in the plant''s supervisor standard."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S1-006' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S1-007', 'source'::public.t3a_content_family, 'TWO CYCLES SHORT OF EIGHTEEN MONTHS', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "TWO CYCLES SHORT OF EIGHTEEN MONTHS", "source_digest": "69245a4289407275bb3e3318e70b095c4ce380a53400b39481b76d0621b8257e", "situation": "You are a research technician at a biotechnology startup, working on a protein encapsulation protocol meant to extend shelf life from six months to eighteen. You have run two experimental cycles. Cycle one reached eight months. Cycle two reached eleven months after you raised the polymer coating concentration. Each cycle costs $12,000 and takes two weeks, and your supervisor has approved one more, starting Monday.\n\nWhat the record shows: the coating is approaching the thickness limit for commercial use, so the concentration cannot rise much further; a postdoctoral researcher suggests changing the crosslinker, a method you have not used, and has two papers on it; the lab holds small scale vials that can test a crosslinker in four days at a fraction of the cost; the raised concentration added three months of stability in cycle two; the lab notebook records both cycles; and the supervisor wants the cycle three design by Friday.", "reveals": [{"code": "R1", "text": "What do the two cycles tell you about the protocol, and what do you do in designing cycle three?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you change in how you are doing this, and what do you keep as it is? Why?", "role": "Information"}, {"code": "R3", "text": "Who or what do you go to, and what do you ask?", "role": "Information"}, {"code": "R4", "text": "Before you rely fully on a different way of doing it, what, if anything, do you do first?", "role": "Information"}, {"code": "R5", "text": "Which work ahead does your approach apply to, and from when?", "role": "Information"}, {"code": "R6", "text": "What, if anything, gets written down, and where?", "role": "Information"}, {"code": "R7", "text": "On Friday your supervisor says: \"You said cycle two showed the concentration can keep rising. Does it?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the coating is approaching the thickness limit for commercial use", "Where the participant meets it": "The situation", "Quoted text": "approaching the thickness limit for commercial use"}, {"Item": "IN2", "Item text": "the raised concentration added three months of stability", "Where the participant meets it": "The situation", "Quoted text": "the raised concentration added three months of stability in cycle two"}, {"Item": "RG1", "Item text": "the raised concentration added three months of stability in cycle two", "Where the participant meets it": "The situation", "Quoted text": "the raised concentration added three months of stability in cycle two"}], "source_sheet": {"d9_situation_class": "SC-D9-2", "workplace_demand": "Designing a third and last approved experimental cycle after two cycles below target.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "Whether the project continues; the cost of the earlier cycles; the postdoctoral researcher''s standing.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the participant should have changed method sooner; that taking or not taking the suggestion shows openness or judgment; anything about the participant''s scientific ability.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "situation_shown": "In the situation: \"the coating is approaching the thickness limit for commercial use.\"", "current_approach": "Raising the polymer coating concentration between cycles.", "indications": [{"id": "IN1", "text": "the coating is approaching the thickness limit for commercial use"}, {"id": "IN2", "text": "the raised concentration added three months of stability"}], "approach_changes": [{"id": "AC1", "text": "change the crosslinker in cycle three"}, {"id": "AC2", "text": "hold the concentration at the cycle two level and change one other variable"}, {"id": "AC3", "text": "run the crosslinker on small scale vials before cycle three"}], "retention_grounds": [{"id": "RG1", "text": "the raised concentration added three months of stability in cycle two"}], "knowledge_sources": [{"id": "KS1", "text": "the postdoctoral researcher and the two papers"}, {"id": "KS2", "text": "the lab notebook for both cycles"}, {"id": "KS3", "text": "the supervisor"}], "open_points": [{"id": "OP1", "text": "how the crosslinker interacts with the current polymer"}, {"id": "OP2", "text": "how close the cycle two coating is to the thickness limit"}], "trial_steps": [{"id": "TS1", "text": "test the crosslinker in small scale vials for four days before committing the full cycle"}], "next_work": [{"id": "NW1", "text": "the cycle three design due Friday"}, {"id": "NW2", "text": "cycle three, starting Monday"}], "record_place": "The lab notebook.", "practice_origin": null, "account_test_point": "R7", "account_test_record": "The situation records that the coating is approaching the thickness limit for commercial use.", "list_note": null, "source_note": null, "situation_class_label": "A result showing the current approach is not producing what the work needs", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D9-S1-007", "stage_code": "S1", "source_version_hash": "69245a4289407275bb3e3318e70b095c4ce380a53400b39481b76d0621b8257e", "serving_eligible": false, "verbatim": "You are a research technician at a biotechnology startup, working on a protein encapsulation protocol meant to extend shelf life from six months to eighteen. You have run two experimental cycles. Cycle one reached eight months. Cycle two reached eleven months after you raised the polymer coating concentration. Each cycle costs $12,000 and takes two weeks, and your supervisor has approved one more, starting Monday.\n\nWhat the record shows: the coating is approaching the thickness limit for commercial use, so the concentration cannot rise much further; a postdoctoral researcher suggests changing the crosslinker, a method you have not used, and has two papers on it; the lab holds small scale vials that can test a crosslinker in four days at a fraction of the cost; the raised concentration added three months of stability in cycle two; the lab notebook records both cycles; and the supervisor wants the cycle three design by Friday."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S1-007' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S1-008', 'source'::public.t3a_content_family, 'THE PRACTICE TEST BEFORE FRIDAY', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE PRACTICE TEST BEFORE FRIDAY", "source_digest": "1627e480aecea2ee3924f6a3fc1c83fb5364e3cd061c802fab92350733580ae9", "situation": "You are a site safety officer at a construction company. You have run safety on residential and light commercial projects for five years. The company has won an eighteen storey project, which requires the site safety officer to hold a fall protection certification you do not yet hold. The course is two days online with a written exam, and the project mobilizes next Monday.\n\nWhat the record shows: you have studied from the course modules in the order they are presented; your practice test on Wednesday showed the most missed questions on fall clearance calculations; the course offers worked examples for each calculation type; a colleague who holds the certification has offered an hour on Wednesday evening; you have a site inspection on your current project on Thursday morning; and your habit of writing a site specific checklist for each new hazard has carried every inspection you have run.", "reveals": [{"code": "R1", "text": "What does the practice test tell you about how you have been studying, and what do you do with the time left?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you change in how you are doing this, and what do you keep as it is? Why?", "role": "Information"}, {"code": "R3", "text": "Who or what do you go to, and what do you ask?", "role": "Information"}, {"code": "R4", "text": "Before you rely fully on a different way of doing it, what, if anything, do you do first?", "role": "Information"}, {"code": "R5", "text": "Which work ahead does your approach apply to, and from when?", "role": "Information"}, {"code": "R6", "text": "What, if anything, gets written down, and where?", "role": "Information"}, {"code": "R7", "text": "On Thursday your supervisor writes: \"You said the practice test was spread evenly across the modules. Was it?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out three items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the most missed practice questions were on fall clearance calculations", "Where the participant meets it": "The situation", "Quoted text": "the most missed questions on fall clearance calculations"}, {"Item": "IN2", "Item text": "the study so far has followed the modules in their order", "Where the participant meets it": "The situation", "Quoted text": "studied from the course modules in the order they are presented"}, {"Item": "RG1", "Item text": "the site specific checklist has carried every inspection", "Where the participant meets it": "The situation", "Quoted text": "your habit of writing a site specific checklist for each new hazard has carried every inspection you have run"}], "source_sheet": {"d9_situation_class": "SC-D9-3 with SC-D9-2", "workplace_demand": "Preparing for a required certification exam within the week while keeping current safety duties.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "Whether the participant passes; the practice result as a measure of the participant; the cost of an external consultant.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": "SENSITIVE_CONTENT", "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "Anything about the participant''s knowledge, ability or speed; the practice result read as a fact about the participant; any prediction about the exam.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "situation_shown": "In the situation: \"your practice test on Wednesday showed the most missed questions on fall clearance calculations.\"", "current_approach": "Studying the course modules in the order they are presented.", "indications": [{"id": "IN1", "text": "the most missed practice questions were on fall clearance calculations"}, {"id": "IN2", "text": "the study so far has followed the modules in their order"}], "approach_changes": [{"id": "AC1", "text": "move study time to the fall clearance calculations"}, {"id": "AC2", "text": "work the course''s worked examples for each calculation type"}, {"id": "AC3", "text": "take the colleague''s hour on Wednesday evening"}], "retention_grounds": [{"id": "RG1", "text": "the site specific checklist has carried every inspection"}], "knowledge_sources": [{"id": "KS1", "text": "the colleague who holds the certification"}, {"id": "KS2", "text": "the course''s worked examples"}, {"id": "KS3", "text": "the supervisor"}], "open_points": [{"id": "OP1", "text": "which calculation types the exam weights most"}, {"id": "OP2", "text": "how the clearance calculation applies on an eighteen storey site"}], "trial_steps": [{"id": "TS1", "text": "work one set of worked examples and retake the calculation questions before moving on"}], "next_work": [{"id": "NW1", "text": "Thursday''s site inspection"}, {"id": "NW2", "text": "the exam"}, {"id": "NW3", "text": "the eighteen storey project from Monday"}], "record_place": "The participant''s study plan for the course.", "practice_origin": null, "account_test_point": "R7", "account_test_record": "The situation records that the most missed practice questions were on fall clearance calculations.", "list_note": null, "source_note": null, "situation_class_label": "A requirement not met before, now needed for the work", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D9-S1-008", "stage_code": "S1", "source_version_hash": "1627e480aecea2ee3924f6a3fc1c83fb5364e3cd061c802fab92350733580ae9", "serving_eligible": false, "verbatim": "You are a site safety officer at a construction company. You have run safety on residential and light commercial projects for five years. The company has won an eighteen storey project, which requires the site safety officer to hold a fall protection certification you do not yet hold. The course is two days online with a written exam, and the project mobilizes next Monday.\n\nWhat the record shows: you have studied from the course modules in the order they are presented; your practice test on Wednesday showed the most missed questions on fall clearance calculations; the course offers worked examples for each calculation type; a colleague who holds the certification has offered an hour on Wednesday evening; you have a site inspection on your current project on Thursday morning; and your habit of writing a site specific checklist for each new hazard has carried every inspection you have run."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S1-008' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S1-009', 'source'::public.t3a_content_family, 'TAUGHT BY A MEMBER OF YOUR OWN TEAM', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "TAUGHT BY A MEMBER OF YOUR OWN TEAM", "source_digest": "be4bf7999d02e249fc1945449d792651ffbc1e5e774af34e8a1f5d21d8eaa18d", "situation": "You are a marketing manager at a national retail company and you lead a team of eight. The company has started a mentoring program that pairs managers with team members who work in digital channels, and you are paired with a social media specialist on your own team, who now takes you through digital strategy each week. Your campaigns in print and broadcast have met their targets for years.\n\nWhat the record shows: at the first session the specialist brought an agenda on short video reach, reels strategy and influencer return metrics; several of the terms used were new to you; the specialist offered to send a glossary and a dashboard walkthrough; in reviewing your draft presentation to the leadership team, the specialist found that one engagement figure you used counts views, not engagements; your presentation is on Friday; and your campaign planning template has carried every campaign that met its targets.", "reveals": [{"code": "R1", "text": "What does the first session tell you about how to use the mentoring, and what do you do next?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you change in how you are doing this, and what do you keep as it is? Why?", "role": "Information"}, {"code": "R3", "text": "Who or what do you go to, and what do you ask?", "role": "Information"}, {"code": "R4", "text": "Before you rely fully on a different way of doing it, what, if anything, do you do first?", "role": "Information"}, {"code": "R5", "text": "Which work ahead does your approach apply to, and from when?", "role": "Information"}, {"code": "R6", "text": "What, if anything, gets written down, and where?", "role": "Information"}, {"code": "R7", "text": "Before Friday the specialist writes: \"You said the engagement figure in the deck was checked. Was it?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the engagement figure in the draft counts views, not engagements", "Where the participant meets it": "The situation", "Quoted text": "counts views, not engagements"}, {"Item": "IN2", "Item text": "several of the terms in the first session were new to the participant", "Where the participant meets it": "The situation", "Quoted text": "several of the terms used were new to you"}, {"Item": "RG1", "Item text": "the campaign planning template has carried every campaign that met its targets", "Where the participant meets it": "The situation", "Quoted text": "your campaign planning template has carried every campaign that met its targets"}], "source_sheet": {"d9_situation_class": "SC-D9-5", "workplace_demand": "Using a mentoring program in which a member of the participant''s own team takes them through a new field.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The reporting relationship; the age or tenure of either person; how others view the program.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "Anything about age, generation or tenure; that taking the correction shows humility or its absence; how much the participant knows about digital channels.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "situation_shown": "In the situation: \"one engagement figure you used counts views, not engagements.\"", "current_approach": "Planning campaigns with the participant''s own campaign planning template.", "indications": [{"id": "IN1", "text": "the engagement figure in the draft counts views, not engagements"}, {"id": "IN2", "text": "several of the terms in the first session were new to the participant"}], "approach_changes": [{"id": "AC1", "text": "correct the engagement figure before Friday"}, {"id": "AC2", "text": "ask for the glossary and the dashboard walkthrough"}, {"id": "AC3", "text": "set the next session''s agenda around the leadership presentation"}], "retention_grounds": [{"id": "RG1", "text": "the campaign planning template has carried every campaign that met its targets"}], "knowledge_sources": [{"id": "KS1", "text": "the specialist"}, {"id": "KS2", "text": "the glossary the specialist offered"}, {"id": "KS3", "text": "the dashboard walkthrough"}], "open_points": [{"id": "OP1", "text": "what each metric in the presentation counts"}, {"id": "OP2", "text": "how the dashboard defines an engagement"}], "trial_steps": [{"id": "TS1", "text": "rework one slide with the specialist before revising the whole deck"}], "next_work": [{"id": "NW1", "text": "Friday''s leadership presentation"}, {"id": "NW2", "text": "the next mentoring session"}], "record_place": "The presentation''s notes.", "practice_origin": null, "account_test_point": "R7", "account_test_record": "The situation records that the engagement figure in the draft counts views, not engagements.", "list_note": null, "source_note": null, "situation_class_label": "Another person''s method for the work available to the participant", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D9-S1-009", "stage_code": "S1", "source_version_hash": "be4bf7999d02e249fc1945449d792651ffbc1e5e774af34e8a1f5d21d8eaa18d", "serving_eligible": false, "verbatim": "You are a marketing manager at a national retail company and you lead a team of eight. The company has started a mentoring program that pairs managers with team members who work in digital channels, and you are paired with a social media specialist on your own team, who now takes you through digital strategy each week. Your campaigns in print and broadcast have met their targets for years.\n\nWhat the record shows: at the first session the specialist brought an agenda on short video reach, reels strategy and influencer return metrics; several of the terms used were new to you; the specialist offered to send a glossary and a dashboard walkthrough; in reviewing your draft presentation to the leadership team, the specialist found that one engagement figure you used counts views, not engagements; your presentation is on Friday; and your campaign planning template has carried every campaign that met its targets."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S1-009' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S1-010', 'source'::public.t3a_content_family, 'THE PORTFOLIO WITH PRODUCTS YOUR FIRM DOES NOT USE', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE PORTFOLIO WITH PRODUCTS YOUR FIRM DOES NOT USE", "source_digest": "282199026d5841bc3f0cabfccbd3a4cd8efd2d09aafc73ceced9bc1b43ccf9b7", "situation": "You are a financial advisor at a wealth management firm and you have advised on retirement planning for six years. A new client, a retired economics professor, has transferred her portfolio to you and asked for a review meeting on Tuesday. Her portfolio holds covered call exchange traded funds, buffer funds and a structured note tied to a commodity index, which your firm does not usually recommend.\n\nWhat the record shows: the firm''s research team can provide product summaries, but not before Monday; each product''s issuer publishes a prospectus and a fact sheet; a senior advisor on another team has managed structured notes; the structured note has a call date in six weeks; your firm''s review template covers suitability, fees and risk for any holding; and the meeting is on Tuesday.", "reveals": [{"code": "R1", "text": "What does the portfolio tell you about how you prepare for Tuesday, and what do you do first?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you change in how you are doing this, and what do you keep as it is? Why?", "role": "Information"}, {"code": "R3", "text": "Who or what do you go to, and what do you ask?", "role": "Information"}, {"code": "R4", "text": "Before you rely fully on a different way of doing it, what, if anything, do you do first?", "role": "Information"}, {"code": "R5", "text": "Which work ahead does your approach apply to, and from when?", "role": "Information"}, {"code": "R6", "text": "What, if anything, gets written down, and where?", "role": "Information"}, {"code": "R7", "text": "On Monday your supervisor asks: \"You said the structured note has no call date. Is that right?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the structured note has a call date in six weeks", "Where the participant meets it": "The situation", "Quoted text": "the structured note has a call date in six weeks"}, {"Item": "IN2", "Item text": "the research summaries will not be ready before Monday", "Where the participant meets it": "The situation", "Quoted text": "can provide product summaries, but not before Monday"}, {"Item": "RG1", "Item text": "the firm''s review template covers suitability, fees and risk for any holding", "Where the participant meets it": "The situation", "Quoted text": "your firm''s review template covers suitability, fees and risk for any holding"}], "source_sheet": {"d9_situation_class": "SC-D9-4", "workplace_demand": "Preparing a portfolio review on products outside the participant''s usual practice.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The client''s expertise; why she transferred; whether the products are suitable.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "How much the participant knows about the products; that seeking help shows a gap; any comparison of the participant with the client.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "situation_shown": "In the situation: \"covered call exchange traded funds, buffer funds and a structured note tied to a commodity index.\"", "current_approach": "Reviewing holdings with the firm''s review template for retirement products.", "indications": [{"id": "IN1", "text": "the structured note has a call date in six weeks"}, {"id": "IN2", "text": "the research summaries will not be ready before Monday"}], "approach_changes": [{"id": "AC1", "text": "read each prospectus and fact sheet before Monday"}, {"id": "AC2", "text": "take the structured note to the senior advisor"}, {"id": "AC3", "text": "tell the client at the meeting which points are still being reviewed"}], "retention_grounds": [{"id": "RG1", "text": "the firm''s review template covers suitability, fees and risk for any holding"}], "knowledge_sources": [{"id": "KS1", "text": "each issuer''s prospectus and fact sheet"}, {"id": "KS2", "text": "the research team''s summaries, from Monday"}, {"id": "KS3", "text": "the senior advisor who has managed structured notes"}], "open_points": [{"id": "OP1", "text": "what the structured note''s call date means for the client"}, {"id": "OP2", "text": "how each product''s fees compare with the firm''s usual holdings"}], "trial_steps": [{"id": "TS1", "text": "run the review template on one product with the senior advisor before the full portfolio"}], "next_work": [{"id": "NW1", "text": "Tuesday''s review meeting"}, {"id": "NW2", "text": "the structured note''s call date in six weeks"}], "record_place": "The client file.", "practice_origin": null, "account_test_point": "R7", "account_test_record": "The situation records that the structured note has a call date in six weeks.", "list_note": null, "source_note": null, "situation_class_label": "Work outside the work the participant has done before", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D9-S1-010", "stage_code": "S1", "source_version_hash": "282199026d5841bc3f0cabfccbd3a4cd8efd2d09aafc73ceced9bc1b43ccf9b7", "serving_eligible": false, "verbatim": "You are a financial advisor at a wealth management firm and you have advised on retirement planning for six years. A new client, a retired economics professor, has transferred her portfolio to you and asked for a review meeting on Tuesday. Her portfolio holds covered call exchange traded funds, buffer funds and a structured note tied to a commodity index, which your firm does not usually recommend.\n\nWhat the record shows: the firm''s research team can provide product summaries, but not before Monday; each product''s issuer publishes a prospectus and a fact sheet; a senior advisor on another team has managed structured notes; the structured note has a call date in six weeks; your firm''s review template covers suitability, fees and risk for any holding; and the meeting is on Tuesday."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S1-010' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S2-001', 'source'::public.t3a_content_family, 'THE MIGRATION BROUGHT FORWARD TO THIS WEEKEND', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE MIGRATION BROUGHT FORWARD TO THIS WEEKEND", "source_digest": "f201b323db150360313c7ee6bda24e95663b42be73cfad96027f72d783fa05db", "mentor_brief": "The mentor reads the scripted lines of the technology director. The mentor forms no view of how readily the participant takes in what is new and records nothing about it. No escalation, no repetition, no expressive reaction. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say. Nothing observed about the person is recordable: only what the participant states about the approach to the work.", "participant_pre_brief": "You are a systems analyst in the information technology department of a holding company. The client portfolio platform was to move from an on premises server to a cloud system next month, after a full rehearsal. This morning the technology director told you the server license expires in seventy two hours and the migration must happen this weekend, with no rehearsal. What the record shows: you have completed the vendor''s online course for the cloud platform but have not run a live migration; the migration tool automates seventy percent of the transfer, and the remaining thirty percent, the custom interfaces and the legacy data mappings, is set by hand; the vendor''s support line has a four hour callback queue; a colleague in another office ran a migration on the same platform last year; the department''s change procedure requires a validation check after any data move; and your practice of validating every data move against a record count has caught every error in your past three projects.", "script": [{"beat": "B1", "type": "SAY", "spoken": "The migration is this weekend. I would like to hear how you are going about it. Go ahead when you are ready.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What does this tell you about the work, and what, if anything, do you change or keep in how you do it?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Who or what are you going to, what would you ask, and would you try anything out first?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "Which work does your approach apply to, from when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said the tool handles the legacy mappings. Does it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists four sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists two trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the remaining thirty percent of the transfer is set by hand", "Where the participant meets it": "The pre-brief", "Quoted text": "the remaining thirty percent, the custom interfaces and the legacy data mappings, is set by hand"}, {"Item": "IN2", "Item text": "there is no rehearsal before the live migration", "Where the participant meets it": "The pre-brief", "Quoted text": "must happen this weekend, with no rehearsal"}, {"Item": "RG1", "Item text": "validating every data move against a record count has caught every error", "Where the participant meets it": "The pre-brief", "Quoted text": "your practice of validating every data move against a record count has caught every error in your past three projects"}], "source_sheet": {"d9_situation_class": "SC-D9-3", "workplace_demand": "Preparing a live platform migration brought forward with no rehearsal.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The vendor dispute; whether the timeline is reasonable; the technology director''s decision.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "How quickly the participant can learn the platform; that keeping the record count check shows caution or rigidity; anything about the participant''s training.", "compatibility_class": "S2-SEVEN-BEAT", "situation_shown": "In the pre-brief: \"the remaining thirty percent, the custom interfaces and the legacy data mappings, is set by hand.\"", "current_approach": "Validating every data move against a record count, on a platform the participant has trained on but not migrated.", "indications": [{"id": "IN1", "text": "the remaining thirty percent of the transfer is set by hand"}, {"id": "IN2", "text": "there is no rehearsal before the live migration"}], "approach_changes": [{"id": "AC1", "text": "set the legacy mappings by hand on a copy before the live run"}, {"id": "AC2", "text": "book the vendor callback now for the weekend window"}, {"id": "AC3", "text": "run the cutover in two stages, interfaces after the data"}], "retention_grounds": [{"id": "RG1", "text": "validating every data move against a record count has caught every error"}], "knowledge_sources": [{"id": "KS1", "text": "the colleague who ran a migration on the same platform last year"}, {"id": "KS2", "text": "the vendor''s support line"}, {"id": "KS3", "text": "the vendor''s online course material"}, {"id": "KS4", "text": "the technology director"}], "open_points": [{"id": "OP1", "text": "how the legacy data mappings are set on the cloud platform"}, {"id": "OP2", "text": "which custom interfaces carry live client data"}], "trial_steps": [{"id": "TS1", "text": "move one client portfolio first and validate it before the rest"}, {"id": "TS2", "text": "set the mappings on a copy of the data before the live run"}], "next_work": [{"id": "NW1", "text": "this weekend''s migration"}, {"id": "NW2", "text": "the post migration validation on Monday"}], "record_place": "The department''s change record.", "practice_origin": null, "account_test_point": "B6", "account_test_record": "The situation records that the legacy data mappings are set by hand, not by the tool.", "list_note": null, "source_note": null, "situation_class_label": "A tool or system not used before, now required for the work", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D9-S2-001", "stage_code": "S2", "source_version_hash": "f201b323db150360313c7ee6bda24e95663b42be73cfad96027f72d783fa05db", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S2-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S2-002', 'source'::public.t3a_content_family, 'THE BOARD MEMBER WHO SAYS THE MODEL IS WRONG', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE BOARD MEMBER WHO SAYS THE MODEL IS WRONG", "source_digest": "173721be43fa1a2a2b30368381b904f05d0fa15183ceff8e327ad92df6a531fe", "mentor_brief": "The mentor reads the scripted lines of the senior scientist. The mentor forms no view of how readily the participant takes in what is new and records nothing about it. No escalation, no repetition, no expressive reaction. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say. Nothing observed about the person is recordable: only what the participant states about the approach to the work.", "participant_pre_brief": "You are a research associate at an applied sciences institute. You presented a predictive maintenance model for pipeline infrastructure to the research advisory board. The model, trained on five years of inspection data, found ultrasonic thickness readings a weaker predictor of failure than environmental and operating variables together. A senior scientist on the board, whose published work rests on thickness readings, said the model is overfit to a narrow dataset and that the feature selection is wrong. What the record shows: the model was validated on a held out year of inspections; the dataset covers one region''s pipelines only; the senior scientist has offered to review your feature selection; the institute''s analytics platform can rerun the model on another region''s data within a week; and the board meets again in a month.", "script": [{"beat": "B1", "type": "SAY", "spoken": "I said in the meeting that your model is overfit. I would like to hear where you stand on that now. Go ahead.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What does this tell you about the work, and what, if anything, do you change or keep in how you do it?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Who or what are you going to, what would you ask, and would you try anything out first?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "Which work does your approach apply to, from when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said the dataset covers every region. Does it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the dataset covers one region''s pipelines only", "Where the participant meets it": "The pre-brief", "Quoted text": "the dataset covers one region''s pipelines only"}, {"Item": "IN2", "Item text": "the senior scientist says the feature selection is wrong", "Where the participant meets it": "The pre-brief", "Quoted text": "the feature selection is wrong"}, {"Item": "RG1", "Item text": "the model was validated on a held out year of inspections", "Where the participant meets it": "The pre-brief", "Quoted text": "the model was validated on a held out year of inspections"}], "source_sheet": {"d9_situation_class": "SC-D9-7 with SC-D9-1", "workplace_demand": "Responding to a senior expert''s challenge to the participant''s findings.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "Who is right about thickness readings; the senior scientist''s standing; how the meeting felt.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That holding the findings shows confidence or stubbornness; that revising them shows openness or giving way; anything about the participant''s seniority or age.", "compatibility_class": "S2-SEVEN-BEAT", "situation_shown": "In the pre-brief: \"said the model is overfit to a narrow dataset and that the feature selection is wrong.\"", "current_approach": "The model as presented, with its feature selection and its held out year validation.", "indications": [{"id": "IN1", "text": "the dataset covers one region''s pipelines only"}, {"id": "IN2", "text": "the senior scientist says the feature selection is wrong"}], "approach_changes": [{"id": "AC1", "text": "rerun the model on another region''s data before the next board meeting"}, {"id": "AC2", "text": "take up the senior scientist''s offer to review the feature selection"}, {"id": "AC3", "text": "state the one region limit in the findings"}], "retention_grounds": [{"id": "RG1", "text": "the model was validated on a held out year of inspections"}], "knowledge_sources": [{"id": "KS1", "text": "the senior scientist''s review"}, {"id": "KS2", "text": "the institute''s analytics platform"}, {"id": "KS3", "text": "the five years of inspection data"}], "open_points": [{"id": "OP1", "text": "which part of the feature selection the senior scientist considers wrong"}, {"id": "OP2", "text": "whether the result holds on another region''s data"}], "trial_steps": [{"id": "TS1", "text": "rerun the model on another region''s data before revising the findings"}], "next_work": [{"id": "NW1", "text": "the findings for next month''s board meeting"}, {"id": "NW2", "text": "the feature selection review"}], "record_place": "The project''s model record.", "practice_origin": null, "account_test_point": "B6", "account_test_record": "The situation records that the dataset covers one region''s pipelines only.", "list_note": null, "source_note": null, "situation_class_label": "An approach already used, challenged, with grounds both to keep and to change it", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D9-S2-002", "stage_code": "S2", "source_version_hash": "173721be43fa1a2a2b30368381b904f05d0fa15183ceff8e327ad92df6a531fe", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S2-002' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S2-003', 'source'::public.t3a_content_family, 'TWENTY HOURS OF COURSE IN FOUR DAYS', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "TWENTY HOURS OF COURSE IN FOUR DAYS", "source_digest": "468ff6a4db7a010d901c16b2fa9c54f87ee0ce79c5d2a6dad9c2f3a14fbd3438", "mentor_brief": "The mentor reads the scripted lines of the maintenance supervisor. The mentor forms no view of how readily the participant takes in what is new and records nothing about it. No escalation, no repetition, no expressive reaction. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say. Nothing observed about the person is recordable: only what the participant states about the approach to the work.", "participant_pre_brief": "You are an aircraft maintenance technician at an aviation services company. A new regulatory requirement says every technician must complete a module on the fault detection software the hangar uses on structural inspection data, by Friday. The module is a twenty hour online course with a proctored exam. What the record shows: you have worked through the modules in the order they are presented and are four hours into one module; the course offers a worked case section using inspection data like the hangar''s; the hangar''s lead inspector uses the software daily and has offered an hour on Wednesday; the software''s operating manual is on the hangar workstation; and your practice of cross checking any flagged finding by hand inspection is in the hangar''s procedure.", "script": [{"beat": "B1", "type": "SAY", "spoken": "You have the module to finish by Friday. Tell me how it is going and what you are doing. Go ahead.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What does this tell you about the work, and what, if anything, do you change or keep in how you do it?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Who or what are you going to, what would you ask, and would you try anything out first?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "Which work does your approach apply to, from when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said the course has no worked cases. Does it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the participant is four hours into one module", "Where the participant meets it": "The pre-brief", "Quoted text": "are four hours into one module"}, {"Item": "IN2", "Item text": "the course offers a worked case section on inspection data", "Where the participant meets it": "The pre-brief", "Quoted text": "offers a worked case section using inspection data like the hangar''s"}, {"Item": "RG1", "Item text": "cross checking flagged findings by hand inspection is in the hangar''s procedure", "Where the participant meets it": "The pre-brief", "Quoted text": "your practice of cross checking any flagged finding by hand inspection is in the hangar''s procedure"}], "source_sheet": {"d9_situation_class": "SC-D9-3", "workplace_demand": "Completing a required course on a software tool by a regulatory date.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "Whether the participant passes; the regulator''s decision; the time a module takes as a fact about the participant.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": "SENSITIVE_CONTENT", "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "Anything about the participant''s education, mathematics or speed; the four hours read as a fact about the participant; any prediction about the exam.", "compatibility_class": "S2-SEVEN-BEAT", "situation_shown": "In the pre-brief: \"are four hours into one module.\"", "current_approach": "Working through the course modules in the order they are presented.", "indications": [{"id": "IN1", "text": "the participant is four hours into one module"}, {"id": "IN2", "text": "the course offers a worked case section on inspection data"}], "approach_changes": [{"id": "AC1", "text": "move to the worked case section before finishing the theory modules"}, {"id": "AC2", "text": "take the lead inspector''s hour on Wednesday"}, {"id": "AC3", "text": "work through the operating manual on the hangar workstation"}], "retention_grounds": [{"id": "RG1", "text": "cross checking flagged findings by hand inspection is in the hangar''s procedure"}], "knowledge_sources": [{"id": "KS1", "text": "the lead inspector"}, {"id": "KS2", "text": "the course''s worked case section"}, {"id": "KS3", "text": "the software''s operating manual"}], "open_points": [{"id": "OP1", "text": "how the software''s flags relate to the hand inspection steps"}, {"id": "OP2", "text": "which modules the exam covers most"}], "trial_steps": [{"id": "TS1", "text": "work one worked case end to end before returning to the theory modules"}], "next_work": [{"id": "NW1", "text": "the module and exam by Friday"}, {"id": "NW2", "text": "the next structural inspection using the software"}], "record_place": "The participant''s training record.", "practice_origin": null, "account_test_point": "B6", "account_test_record": "The situation records that the course offers a worked case section.", "list_note": null, "source_note": null, "situation_class_label": "A tool or system not used before, now required for the work", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D9-S2-003", "stage_code": "S2", "source_version_hash": "468ff6a4db7a010d901c16b2fa9c54f87ee0ce79c5d2a6dad9c2f3a14fbd3438", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S2-003' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S2-005', 'source'::public.t3a_content_family, 'THE CONTROLLER NOBODY DOCUMENTED', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE CONTROLLER NOBODY DOCUMENTED", "source_digest": "6eaeeb0778bb4772366ae4be26873c8d4b8438dcf4e067029d37d437a2bd9388", "mentor_brief": "The mentor reads the scripted lines of the plant manager. The mentor forms no view of how readily the participant takes in what is new and records nothing about it. No escalation, no repetition, no expressive reaction. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say. Nothing observed about the person is recordable: only what the participant states about the approach to the work.", "participant_pre_brief": "You are a process engineer at a manufacturer that has acquired a competitor''s injection molding line. The line is run by a legacy programmable logic controller, the operator who programmed it has retired, and no documentation exists. The line produces a high margin automotive part. What the record shows: one subroutine triggers intermittently, and the line produces a defect on the cycles when it does not trigger; the maintenance software cannot read the controller''s logic; the retired operator''s handwritten shift notes are in the line''s cabinet; the controller maker''s support desk holds manuals for the model; the line has run within specification for three years on the existing logic; and the plant manager wants a recommendation on keeping or replacing the controller by month end.", "script": [{"beat": "B1", "type": "SAY", "spoken": "I need your recommendation on the controller by month end. Tell me where you are. Go ahead.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What does this tell you about the work, and what, if anything, do you change or keep in how you do it?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Who or what are you going to, what would you ask, and would you try anything out first?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "Which work does your approach apply to, from when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said the subroutine triggers on every cycle. Does it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the line produces a defect on the cycles when the subroutine does not trigger", "Where the participant meets it": "The pre-brief", "Quoted text": "the line produces a defect on the cycles when it does not trigger"}, {"Item": "IN2", "Item text": "no documentation exists for the controller", "Where the participant meets it": "The pre-brief", "Quoted text": "the operator who programmed it has retired, and no documentation exists"}, {"Item": "RG1", "Item text": "the line has run within specification for three years on the existing logic", "Where the participant meets it": "The pre-brief", "Quoted text": "the line has run within specification for three years on the existing logic"}], "source_sheet": {"d9_situation_class": "SC-D9-6", "workplace_demand": "Working out an undocumented controller and recommending whether to keep or replace it.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The acquisition; the retired operator; the cost of replacement.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "How much the participant knows about legacy controllers; that recommending to keep or replace shows caution or ambition; any comparison with the retired operator.", "compatibility_class": "S2-SEVEN-BEAT", "situation_shown": "In the pre-brief: \"the line produces a defect on the cycles when it does not trigger.\"", "current_approach": "Running the line on the existing, undocumented controller logic.", "indications": [{"id": "IN1", "text": "the line produces a defect on the cycles when the subroutine does not trigger"}, {"id": "IN2", "text": "no documentation exists for the controller"}], "approach_changes": [{"id": "AC1", "text": "map the controller''s logic from the program before any change"}, {"id": "AC2", "text": "document the subroutine before deciding on replacement"}, {"id": "AC3", "text": "replace the controller with the integrated control system"}], "retention_grounds": [{"id": "RG1", "text": "the line has run within specification for three years on the existing logic"}], "knowledge_sources": [{"id": "KS1", "text": "the retired operator''s handwritten shift notes"}, {"id": "KS2", "text": "the controller maker''s support desk"}, {"id": "KS3", "text": "the line''s cycle records"}], "open_points": [{"id": "OP1", "text": "what the intermittent subroutine does"}, {"id": "OP2", "text": "what the replacement system would need to reproduce"}], "trial_steps": [{"id": "TS1", "text": "run the line with the subroutine logged on a test shift before drawing a conclusion"}], "next_work": [{"id": "NW1", "text": "the recommendation to the plant manager by month end"}, {"id": "NW2", "text": "the line''s next production run"}], "record_place": "The line''s engineering file.", "practice_origin": null, "account_test_point": "B6", "account_test_record": "The situation records that the subroutine triggers intermittently.", "list_note": null, "source_note": null, "situation_class_label": "Knowledge the work depends on, undocumented or held only by others", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D9-S2-005", "stage_code": "S2", "source_version_hash": "6eaeeb0778bb4772366ae4be26873c8d4b8438dcf4e067029d37d437a2bd9388", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S2-005' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S2-006', 'source'::public.t3a_content_family, 'FIVE REVIEWERS, THREE DAYS', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "FIVE REVIEWERS, THREE DAYS", "source_digest": "4712660ca868cb845702eebc1b6b79ba86f9a68f72cbd0dc2d3ec8f2d96cf644", "mentor_brief": "The mentor reads the scripted lines of the creative director. The mentor forms no view of how readily the participant takes in what is new and records nothing about it. No escalation, no repetition, no expressive reaction. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say. Nothing observed about the person is recordable: only what the participant states about the approach to the work.", "participant_pre_brief": "You are a graphic designer at a creative agency, redesigning the brand identity for a retailer moving from stores to online selling. You presented your first concept last week. What the record shows: the client''s chief executive wants the identity bold and futuristic; the client''s marketing head wants it warm and approachable; the creative director says the typeface is wrong; the agency''s user experience lead says the color palette fails accessibility contrast standards; the client''s product team says the logo must work as a small app icon; the client''s chief executive has also received a different direction from an outside brand consultant; the concept''s layout grid tested well with the client''s customers; and the revised concept is due in three days.", "script": [{"beat": "B1", "type": "SAY", "spoken": "You have the revised concept due in three days. Tell me how you are handling the feedback. Go ahead.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": 