", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out three indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists four sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the color palette fails accessibility contrast standards", "Where the participant meets it": "The pre-brief", "Quoted text": "the color palette fails accessibility contrast standards"}, {"Item": "IN2", "Item text": "the logo must work as a small app icon", "Where the participant meets it": "The pre-brief", "Quoted text": "the logo must work as a small app icon"}, {"Item": "IN3", "Item text": "the chief executive and the marketing head want different directions", "Where the participant meets it": "The pre-brief", "Quoted text": "wants it warm and approachable"}, {"Item": "RG1", "Item text": "the concept''s layout grid tested well with the client''s customers", "Where the participant meets it": "The pre-brief", "Quoted text": "the concept''s layout grid tested well with the client''s customers"}], "source_sheet": {"d9_situation_class": "SC-D9-1", "workplace_demand": "Revising a brand concept after feedback from five reviewers in three days.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "Which reviewer is senior; the outside consultant; taste.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the participant pleases everyone or holds their own view; any judgment of the participant''s design instinct; that adopting the consultant''s direction is better or worse.", "compatibility_class": "S2-SEVEN-BEAT", "situation_shown": "In the pre-brief: \"the agency''s user experience lead says the color palette fails accessibility contrast standards.\"", "current_approach": "The first concept, with its layout grid, typeface and palette.", "indications": [{"id": "IN1", "text": "the color palette fails accessibility contrast standards"}, {"id": "IN2", "text": "the logo must work as a small app icon"}, {"id": "IN3", "text": "the chief executive and the marketing head want different directions"}], "approach_changes": [{"id": "AC1", "text": "revise the palette to meet the contrast standard"}, {"id": "AC2", "text": "test the logo at app icon size before other changes"}, {"id": "AC3", "text": "bring the chief executive and the marketing head to one session on direction"}], "retention_grounds": [{"id": "RG1", "text": "the concept''s layout grid tested well with the client''s customers"}], "knowledge_sources": [{"id": "KS1", "text": "the user experience lead"}, {"id": "KS2", "text": "the creative director"}, {"id": "KS3", "text": "the client''s product team"}, {"id": "KS4", "text": "the outside consultant''s direction"}], "open_points": [{"id": "OP1", "text": "what the chief executive means by futuristic"}, {"id": "OP2", "text": "what the outside consultant''s direction rests on"}], "trial_steps": [{"id": "TS1", "text": "produce the logo at icon size and the palette at the contrast standard before reworking the concept"}], "next_work": [{"id": "NW1", "text": "the revised concept in three days"}, {"id": "NW2", "text": "the next client presentation"}], "record_place": "The project''s feedback log.", "practice_origin": null, "account_test_point": "B6", "account_test_record": "The situation records that the color palette fails accessibility contrast standards.", "list_note": null, "source_note": null, "situation_class_label": "Feedback on the participant''s work, given by more than one party", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D9-S2-006", "stage_code": "S2", "source_version_hash": "4712660ca868cb845702eebc1b6b79ba86f9a68f72cbd0dc2d3ec8f2d96cf644", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S2-006' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S2-007', 'source'::public.t3a_content_family, 'THE SHIPMENT FLAGGED FOR DUAL USE', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE SHIPMENT FLAGGED FOR DUAL USE", "source_digest": "76432ca418533d7e495d41e467beee6a029770f6db9bbc5773f38534b6605457", "mentor_brief": "The mentor reads the scripted lines of the trade compliance manager. The mentor forms no view of how readily the participant takes in what is new and records nothing about it. No escalation, no repetition, no expressive reaction. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say. Nothing observed about the person is recordable: only what the participant states about the approach to the work.", "participant_pre_brief": "You are a trade compliance coordinator at an industrial equipment exporter. The company''s trade compliance software flagged a shipment of valve actuators to a new client abroad as a possible dual use item under export controls, and asked for manual review. Your work so far has been in tariff classification, not export controls. What the record shows: the shipment leaves in forty eight hours; the sales director wants it cleared; the export control list and its technical thresholds are published by the government; the compliance manager returns tomorrow; the actuator''s technical data sheet is in the product file; and your practice of holding any shipment with an open flag until it is resolved is in the company''s compliance procedure.", "script": [{"beat": "B1", "type": "SAY", "spoken": "I am back. The actuator shipment was flagged. Tell me where it stands. Go ahead.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What does this tell you about the work, and what, if anything, do you change or keep in how you do it?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Who or what are you going to, what would you ask, and would you try anything out first?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "Which work does your approach apply to, from when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said the sales director has cleared it. Has he?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the software flagged the shipment as a possible dual use item", "Where the participant meets it": "The pre-brief", "Quoted text": "flagged a shipment of valve actuators to a new client abroad as a possible dual use item"}, {"Item": "IN2", "Item text": "the shipment leaves in forty eight hours", "Where the participant meets it": "The pre-brief", "Quoted text": "the shipment leaves in forty eight hours"}, {"Item": "RG1", "Item text": "holding any shipment with an open flag is in the compliance procedure", "Where the participant meets it": "The pre-brief", "Quoted text": "your practice of holding any shipment with an open flag until it is resolved is in the company''s compliance procedure"}], "source_sheet": {"d9_situation_class": "SC-D9-3", "workplace_demand": "Handling an export control flag outside the participant''s usual classification work.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The sales relationship; the client''s country; whether the item is in fact controlled.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "How much the participant knows about export controls; that holding the shipment shows caution or obstruction; anything about the client''s or participant''s origin.", "compatibility_class": "S2-SEVEN-BEAT", "situation_shown": "In the pre-brief: \"flagged a shipment of valve actuators to a new client abroad as a possible dual use item.\"", "current_approach": "Tariff classification, and holding shipments with an open flag until resolved.", "indications": [{"id": "IN1", "text": "the software flagged the shipment as a possible dual use item"}, {"id": "IN2", "text": "the shipment leaves in forty eight hours"}], "approach_changes": [{"id": "AC1", "text": "check the actuator''s data sheet against the published thresholds"}, {"id": "AC2", "text": "add an export control check to the order process for new clients"}, {"id": "AC3", "text": "hold the shipment until the review is complete"}], "retention_grounds": [{"id": "RG1", "text": "holding any shipment with an open flag is in the compliance procedure"}], "knowledge_sources": [{"id": "KS1", "text": "the published export control list and thresholds"}, {"id": "KS2", "text": "the actuator''s technical data sheet"}, {"id": "KS3", "text": "the compliance manager"}], "open_points": [{"id": "OP1", "text": "which threshold the actuators come close to"}, {"id": "OP2", "text": "what the order process checks for a new client"}], "trial_steps": [{"id": "TS1", "text": "check one actuator model against the thresholds with the compliance manager before writing the process"}], "next_work": [{"id": "NW1", "text": "this shipment''s release decision"}, {"id": "NW2", "text": "orders for new clients from now on"}], "record_place": "The compliance file for the shipment.", "practice_origin": null, "account_test_point": "B6", "account_test_record": "The situation records that the sales director wants the shipment cleared and the compliance manager has not reviewed it.", "list_note": null, "source_note": null, "situation_class_label": "A rule or procedure not used before, now required for the work", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D9-S2-007", "stage_code": "S2", "source_version_hash": "76432ca418533d7e495d41e467beee6a029770f6db9bbc5773f38534b6605457", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S2-007' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S2-008', 'source'::public.t3a_content_family, 'THE SKILLS MAP AND THE MOVING BENCHMARK', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE SKILLS MAP AND THE MOVING BENCHMARK", "source_digest": "ece753068254cb71b5b3e4e409c8546dd315ce7ed19847a89ed97fcfbe47d24e", "mentor_brief": "The mentor reads the scripted lines of the human resources manager. The mentor forms no view of how readily the participant takes in what is new and records nothing about it. No escalation, no repetition, no expressive reaction. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say. Nothing observed about the person is recordable: only what the participant states about the approach to the work.", "participant_pre_brief": "You are a human resources generalist at a consulting firm. The firm''s skills mapping platform compares each employee''s self rating against project records. For data analytics, the platform lists the firm''s benchmark as business intelligence tool reporting and your project records as spreadsheet reporting only. What the record shows: the firm is moving human resources reporting to its business intelligence tool next quarter; the tool''s vendor runs a free online course; an analyst on the finance team builds dashboards in the tool weekly; since the last review the benchmark has been revised to include predictive analytics; your spreadsheet reports have met every monthly deadline this year; and your manager wants a plan at your meeting on Thursday.", "script": [{"beat": "B1", "type": "SAY", "spoken": "You have seen the skills map. I would like to hear your plan for the data analytics area. Go ahead.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What does this tell you about the work, and what, if anything, do you change or keep in how you do it?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Who or what are you going to, what would you ask, and would you try anything out first?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "Which work does your approach apply to, from when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said the benchmark has not changed since the last review. Has it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": 