  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "FOURTEEN OF TWENTY COULD NOT FINISH", "source_digest": "f0f8f27cb6862c6cd0f6fc635f8d96c2526b705c042017ed3aed6cd222d4a9a7", "mentor_brief": "The mentor reads the scripted lines of the lab lead. The mentor forms no view of how readily the participant takes in what is new and records nothing about it. No escalation, no repetition, no expressive reaction. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say. Nothing observed about the person is recordable: only what the participant states about the approach to the work.", "participant_pre_brief": "You are a product designer at a service company''s innovation lab, leading the physical interface of a customer service kiosk with a voice assistant. Yesterday''s prototype test had twenty users. What the record shows: fourteen of the twenty could not check an order status within sixty seconds; eight users spoke to the screen instead of touching it; the accessibility features were praised by every user who used them; a teammate proposes a voice only design, supported by two other designers; your research notes record a thirty five percent abandonment rate for voice only kiosks in noisy retail settings; the lab can run a ten user test in two days; and the revision is due in ten days.", "script": [{"beat": "B1", "type": "SAY", "spoken": "I have read the test results. Tell me what you are doing with them. Go ahead.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b