ete the task within sixty seconds.", "list_note": null, "source_note": null, "situation_class_label": "A result showing the current approach is not producing what the work needs", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D9-S2-009", "stage_code": "S2", "source_version_hash": "f0f8f27cb6862c6cd0f6fc635f8d96c2526b705c042017ed3aed6cd222d4a9a7", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S2-009' and family = 'source'::public.t3a_content_family;
