  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THREE REQUESTS AT EIGHT ON MONDAY", "source_digest": "7039fbd343692cde565b1fcb8fed49adab5a7e28d53e649568ad5beb32293c31", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are an operations coordinator at a commercial property company managing fourteen properties, five months into the role. At 8:00 AM Monday three requests arrive: the heating and cooling system on floors three to five of the main downtown property failed overnight and one tenant has an investor presentation at 2:00 PM; the finance team asks for your sign off on a quarterly maintenance budget reconciliation due to the chief financial officer by noon Tuesday; and a tenant at a second property has filed a written complaint about parking lot lighting that your predecessor promised to fix by the end of February. What the record shows: the reconciliation spreadsheet contains line items from before your time that you have not seen; the finance analyst who prepared it is available today; your predecessor''s handover notes are on the shared drive; last quarter''s review flagged your region for slow maintenance response; and the triage checklist you have used since starting has carried every week so far."}], "submission_instructions": "Produce a triage plan for the next forty eight hours; a status note to your director for 5:00 PM today; and a log of what you assumed, what you do not know and how you would find it out. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out three items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "NOT SERVED", "basis": "The asynchronous form puts no earlier statement back to the participant"}], "material_map": [{"Item": "IN1", "Item text": "the reconciliation contains line items from before the participant''s time", "Where the participant meets it": "Pack document D1", "Quoted text": "contains line items from before your time that you have not seen"}, {"Item": "IN2", "Item text": "the predecessor promised the lighting fix by the end of February", "Where the participant meets it": "Pack document D1", "Quoted text": "your predecessor promised to fix by the end of February"}, {"Item": "RG1", "Item text": "the triage checklist has carried every week so far", "Where the participant meets it": "Pack document D1", "Quoted text": "the triage checklist you have used since starting has carried every week so far"}], "source_sheet": {"d9_situation_class": "SC-D9-4", "workplace_demand": "Working three urgent requests where one depends on records from before the participant''s time.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where.", "irrelevant_conduct": "The order of the three requests, which is a D3 matter; the predecessor; the tenant''s tone.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "That the participant''s five months show a gap; how much the participant knows about the budget; anything about prioritizing, which is D3''s.", "compatibility_class": "S3-ASYNC-SUBMISSION", "situation_shown": "In the brief: \"the reconciliation spreadsheet contains line items from before your time that you have not seen.\"", "current_approach": "The participant''s weekly triage checklist.", "indications": [{"id": "IN1", "text": "the reconciliation contains line items from before the participant''s time"}, {"id": "IN2", "text": "the predecessor promised the lighting fix by the end of February"}], "approach_changes": [{"id": "AC1", "text": "go through the unfamiliar line items with the finance analyst before signing"}, {"id": "AC2", "text": "read the predecessor''s handover notes on the lighting promise"}, {"id": "AC3", "text": "add a check of open promises to the weekly triage"}], "retention_grounds": [{"id": "RG1", "text": "the triage checklist has carried every week so far"}], "knowledge_sources": [{"id": "KS1", "text": "the finance analyst who prepared the reconciliation"}, {"id": "KS2", "text": "the predecessor''s handover notes"}, {"id": "KS3", "text": "the facilities manager at the downtown property"}], "open_points": [{"id": "OP1", "text": "what each unfamiliar line item covers"}, {"id": "OP2", "text": "what was promised to the tenant, and by whom"}], "trial_steps": [{"id": "TS1", "text": "reconcile the unfamiliar items against last quarter''s figures before signing the whole sheet"}], "next_work": [{"id": "NW1", "text": "the reconciliation due Tuesday"}, {"id": "NW2", "text": "the reply to the tenant''s complaint"}, {"id": "NW3", "text": "the next weekly triage"}], "record_place": "The assumptions and unknowns log.", "practice_origin": null, "list_note": null, "source_note": "Shared Stage 3 project DEMO-02, which also names D3 and D2 among its primary dimensions; one served instance, a separate observation record in each dimension.", "situation_class_label": "Work outside the work the participant has done before", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D9-S3-001", "stage_code": "S3", "source_version_hash": "7039fbd343692cde565b1fcb8fed49adab5a7e28d53e649568ad5beb32293c31", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S3-001' and family 