  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "TWELVE PERCENT ON THE NEW EYEWEAR LINE", "source_digest": "03776947808ea32942744fae2783c433b41f7c10c61c142ff7f300a468f5210f", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are a process improvement analyst at a manufacturer of industrial safety equipment. A new protective eyewear line shares floor space and some assembly steps with the existing hard hat line. Eight weeks after launch, the eyewear line rejects twelve percent of its units against a three percent target, and your vice president wants a recommendation by Friday. What the record shows: after two days on the floor you found that the handoff between sub assembly and final assembly has no checklist; workers rotating from the hard hat line seat lenses with the hard hat line''s method, which misaligns the lens tolerances; the night shift lead uses an informal handoff check and the night shift rejects four percent; the day shift supervisor holds that experienced workers do not need a checklist; the plant''s largest buyer has raised the reject rate on its last quality call; and the hard hat line''s own assembly method holds its reject rate under two percent."}], "submission_instructions": "Produce a recommendation on the handoff, with the problem, the cause you found and the change; a timeline for introducing it, including any trial; and a note to the day shift supervisor setting out the evidence. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out three indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out three items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "NOT SERVED", "basis": "The asynchronous form puts no earlier statement back to the participant"}], "material_map": [{"Item": "IN1", "Item text": "the eyewear line rejects twelve percent against a three percent target", "Where the participant meets it": "Pack document D1", "Quoted text": "rejects twelve percent of its units against a three percent target"}, {"Item": "IN2", "Item text": "the handoff between sub assembly and final assembly has no checklist", "Where the participant meets it": "Pack document D1", "Quoted text": "the handoff between sub assembly and final assembly has no checklist"}, {"Item": "IN3", "Item text": "the night shift''s informal handoff check goes with a four percent reject rate", "Where the participant meets it": "Pack document D1", "Quoted text": "the night shift rejects four percent"}, {"Item": "RG1", "Item text": "the hard hat line''s method holds its reject rate under two percent", "Where the participant meets it": "Pack document D1", "Quoted text": "the hard hat line''s own assembly method holds its reject rate under two percent"}], "source_sheet": {"d9_situation_class": "SC-D9-2 with SC-D9-5", "workplace_demand": "Recommending a change to a production handoff after a high reject rate on a new line.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where.", "irrelevant_conduct": "The day shift supervisor''s tenure and authority; temporary staffing; who is answerable for the rejects, which is D2''s.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "That the day shift supervisor or any worker resists change; that experience is a limit; anything about the age or tenure of anyone on the floor.", "compatibility_class": "S3-ASYNC-SUBMISSION", "situation_shown": "In the brief: \"the handoff between sub assembly and final assembly has no checklist.\"", "current_approach": "The handoff as run without a checklist, with rotating workers using the hard hat line''s seating method.", "indications": [{"id": "IN1", "text": "the eyewear line rejects twelve percent against a three percent target"}, {"id": "IN2", "text": "the handoff between sub assembly and final assembly has no checklist"}, {"id": "IN3", "text": "the night shift''s informal handoff check goes with a four percent reject rate"}], "approach_changes": [{"id": "AC1", "text": "introduce a handoff checklist built on the night shift lead''s check"}, {"id": "AC2", "text": "give rotating workers a lens seating step specific to the eyewear line"}, {"id": "AC3", "text": "keep the hard hat line''s method on the hard hat line unchanged"}], "retention_grounds": [{"id": "RG1", "text": "the hard hat line''s method holds its reject rate under two percent"}], "knowledge_sources": [{"id": "KS1", "text": "the night shift lead''s informal check"}, {"id": "KS2", "text": "the shift leads interviewed on the floor"}, {"id": "KS3", "text": "the quality inspection records"}], "open_points": [{"id": "OP1", "text": "what the night shift lead''s check covers"}, {"id": "OP2", "text": "which tolerance the hard hat seating method misaligns"}], "trial_steps": [{"id": "TS1", "text": "run the checklist on one shift for a week and compare reject rates before rolling it out"}], "next_work": [{"id": "NW1", "text": "Friday''s recommendation"}, {"id": "NW2", "text": "the next buyer quality call"}, {"id": "NW3", "text": "the eyewear line''s next production week"}], "record_place": "The plant''s process change record.", "practice_origin": null, "list_note": null, "source_note": "Shared Stage 3 project DEMO-04, which also names D3 and D2 among its primary dimensions; one served instance, a separate observation record in each dimension.", "situation_class_label": "A result showing the current approach is not producing what the work needs", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D9-S3-002", "stage_code": "S3", "source_version_hash": "03776947808ea32942744fae2783c433b41f7c10c61c142ff7f300a468f5210f", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S3-002' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S3-003', 'source'::public.t3a_content_family, 'A FINDINGS DECK WITH NO TEMPLATE', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "A FINDINGS DECK WITH NO TEMPLATE", "source_digest": "7e1178af628a27536334a8f8be6ef69b9ed29fa078ccef7ffaa657084a13baa6", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are a business analyst at a professional services firm, four months into the role. At 4:30 PM Friday your senior manager writes asking you to lead the initial findings presentation for a regional transit authority''s complaint handling review, using the discovery data; the client meeting is Thursday at 10:00 AM and he will review on Wednesday afternoon. What the record shows: the brief gives no structure, slide count or depth; the discovery package holds six months of complaint volume data, three stakeholder interview transcripts, a process flow of the current handling workflow, and a benchmarking comparison a junior analyst started but did not finish; the shared drive holds three past initial findings presentations, each with a different structure; there is no firm template; and the process flow was confirmed with the client''s staff during discovery."}], "submission_instructions": "Produce a note to your senior manager setting out how you read the request and what you need from him; an outline of the presentation with its sections and its main findings, and how you handle the unfinished benchmarking; and a register of your assumptions and how you would check them. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out three indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "NOT SERVED", "basis": "The asynchronous form puts no earlier statement back to the participant"}], "material_map": [{"Item": "IN1", "Item text": "the brief gives no structure, slide count or depth", "Where the participant meets it": "Pack document D1", "Quoted text": "the brief gives no structure, slide count or depth"}, {"Item": "IN2", "Item text": "the three past presentations each have a different structure", "Where the participant meets it": "Pack document D1", "Quoted text": "three past initial findings presentations, each with a different structure"}, {"Item": "IN3", "Item text": "the benchmarking comparison is unfinished", "Where the participant meets it": "Pack document D1", "Quoted text": "a benchmarking comparison a junior analyst started but did not finish"}, {"Item": "RG1", "Item text": "the process flow was confirmed with the client''s staff during discovery", "Where the participant meets it": "Pack document D1", "Quoted text": "the process flow was confirmed with the client''s staff during discovery"}], "source_sheet": {"d9_situation_class": "SC-D9-6", "workplace_demand": "Building a client presentation from an open request with no template.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where.", "irrelevant_conduct": "The senior manager''s workload; the firm''s practice; the client''s view of the transit service.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "That the participant''s four months in the role show a gap; how well the participant reads ambiguity; anything about communication quality, which is D4''s.", "compatibility_class": "S3-ASYNC-SUBMISSION", "situation_shown": "In the brief: \"the brief gives no structure, slide count or depth.\"", "current_approach": "The discovery package and the confirmed process flow, with no settled structure for the deck.", "indications": [{"id": "IN1", "text": "the brief gives no structure, slide count or depth"}, {"id": "IN2", "text": "the three past presentations each have a different structure"}, {"id": "IN3", "text": "the benchmarking comparison is unfinished"}], "approach_changes": [{"id": "AC1", "text": "send the senior manager a proposed structure before building the deck"}, {"id": "AC2", "text": "base the structure on the past presentation closest to this client"}, {"id": "AC3", "text": "present the benchmarking as incomplete, with its limits stated"}], "retention_grounds": [{"id": "RG1", "text": "the process flow was confirmed with the client''s staff during discovery"}], "knowledge_sources": [{"id": "KS1", "text": "the senior manager"}, {"id": "KS2", "text": "the three past presentations"}, {"id": "KS3", "text": "the junior analyst who started the benchmarking"}], "open_points": [{"id": "OP1", "text": "what depth the client expects at the initial findings stage"}, {"id": "OP2", "text": "which comparators the benchmarking was meant to cover"}], "trial_steps": [{"id": "TS1", "text": "draft the outline of one section and send it before building the rest"}], "next_work": [{"id": "NW1", "text": "Wednesday''s review with the senior manager"}, {"id": "NW2", "text": "Thursday''s client meeting"}], "record_place": "The assumptions register.", "practice_origin": null, "list_note": null, "source_note": "Shared Stage 3 project DEMO-09, which also names D3 and D2 among its primary dimensions; one served instance, a separate observation record in each dimension.", "situation_class_label": "Knowledge the work depends on, undocumented or held only by others", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D9-S3-003", "stage_code": "S3", "source_version_hash": "7e1178af628a27536334a8f8be6ef69b9ed29fa078ccef7ffaa657084a13baa6", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S3-003' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S3-004', 'source'::public.t3a_content_family, 'THE RENEWAL THAT WENT TO TENDER', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE RENEWAL THAT WENT TO TENDER", "source_digest": "e9bb70179ced87190a1b6118b5e0e0994e294cba9d55b7fddec51a35e774aece", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are an account manager at a managed information technology services provider, with twelve accounts. Your largest, a regional healthcare group, was due to renew in six weeks; you sent a renewal proposal three weeks ago with a five percent increase for wider scope. On Tuesday the client''s chief technology officer told you the client will issue a request for proposals instead, that the board wants to benchmark costs, and that the increase was a factor. Your vice president wants a plan by Thursday. What the record shows: your account notes show the last value focused conversation with the client was eight months ago; the quarterly business review was rescheduled twice and held as a twenty minute call; the client''s compliance team raised a data residency question four months ago that was not followed up; your company offers a healthcare compliance module the client has not seen; and your monthly billing reviews have kept the account free of billing disputes for three years."}], "submission_instructions": "Produce a reply to the chief technology officer asking to take part in the process; a plan for the next six weeks covering what you would change in the proposal and in how you manage the account; and a note to your vice president setting out what the account record shows and what you would do differently. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out three indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists four sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out three items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "NOT SERVED", "basis": "The asynchronous form puts no earlier statement back to the participant"}], "material_map": [{"Item": "IN1", "Item text": "the last value focused conversation with the client was eight months ago", "Where the participant meets it": "Pack document D1", "Quoted text": "the last value focused conversation with the client was eight months ago"}, {"Item": "IN2", "Item text": "the compliance team''s question four months ago was not followed up", "Where the participant meets it": "Pack document D1", "Quoted text": "raised a data residency question four months ago that was not followed up"}, {"Item": "IN3", "Item text": "the increase was a factor in the decision", "Where the participant meets it": "Pack document D1", "Quoted text": "the increase was a factor"}, {"Item": "RG1", "Item text": "the monthly billing reviews have kept the account free of billing disputes", "Where the participant meets it": "Pack document D1", "Quoted text": "your monthly billing reviews have kept the account free of billing disputes for three years"}], "source_sheet": {"d9_situation_class": "SC-D9-2", "workplace_demand": "Planning a response after a renewal was turned into an open tender.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where.", "irrelevant_conduct": "Who is answerable for the lost renewal, which is D2''s; the board''s decision; the vice president''s reaction.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "That the participant neglected the account; any judgment of self assessment; how the participant bore the news, which is outside every dimension.", "compatibility_class": "S3-ASYNC-SUBMISSION", "situation_shown": "In the brief: \"your account notes show the last value focused conversation with the client was eight months ago.\"", "current_approach": "Monthly billing reviews and occasional business reviews on each account.", "indications": [{"id": "IN1", "text": "the last value focused conversation with the client was eight months ago"}, {"id": "IN2", "text": "the compliance team''s question four months ago was not followed up"}, {"id": "IN3", "text": "the increase was a factor in the decision"}], "approach_changes": [{"id": "AC1", "text": "hold a full business review with the client before the tender closes"}, {"id": "AC2", "text": "answer the data residency question in the tender response"}, {"id": "AC3", "text": "set a quarterly value review across all twelve accounts"}], "retention_grounds": [{"id": "RG1", "text": "the monthly billing reviews have kept the account free of billing disputes"}], "knowledge_sources": [{"id": "KS1", "text": "the account notes"}, {"id": "KS2", "text": "the client''s compliance team"}, {"id": "KS3", "text": "the vice president"}, {"id": "KS4", "text": "the healthcare compliance module''s product team"}], "open_points": [{"id": "OP1", "text": "what the board''s benchmark will compare"}, {"id": "OP2", "text": "what the data residency question was"}], "trial_steps": [{"id": "TS1", "text": "run the quarterly value review on the two next largest accounts before setting it for all twelve"}], "next_work": [{"id": "NW1", "text": "the plan due Thursday"}, {"id": "NW2", "text": "the tender response within six weeks"}, {"id": "NW3", "text": "the other eleven accounts"}], "record_place": "The account plan in the client record.", "practice_origin": null, "list_note": null, "source_note": "Shared Stage 3 project DEMO-12, also served as SRC-D8-S3-004 and SRC-D4-S3-007; one served instance, a separate observation record in each dimension.", "situation_class_label": "A result showing the current approach is not producing what the work needs", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D9-S3-004", "stage_code": "S3", "source_version_hash": "e9bb70179ced87190a1b6118b5e0e0994e294cba9d55b7fddec51a35e774aece", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S3-004' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S3-005', 'source'::public.t3a_content_family, 'THREE WRONG TRUCKS IN SIX WEEKS', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THREE WRONG TRUCKS IN SIX WEEKS", "source_digest": "0b5a512edbfd6314afd893ea8e2cc57aa418fedd452cc07c04f32a36d91c4349", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are an operations analyst at a freight and warehousing company with three distribution centers. Three times in six weeks at one center, outbound shipments were loaded onto the wrong carrier''s truck. Each time the shift supervisor''s incident report gave the cause as an individual worker''s carelessness. Your director has asked for an independent investigation. What the record shows: the dispatch labels print carrier codes that differ by one character in twelve between the two highest volume carriers; the loading bay where two of the three errors happened has dimmer lighting than the other bays; the warehouse management system lets the label format be changed by configuration; the three incident reports name three different workers; and the center''s scan at the dock door matches the label to the truck on every load where it is used."}], "submission_instructions": "Produce an investigation summary for your director with the timeline, what you observed and what the records show; recommendations on the causes you found, each with a holder and a date; and a log of the evidence and of any inconsistencies in the incident reports. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out three indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists four sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "NOT SERVED", "basis": "The asynchronous form puts no earlier statement back to the participant"}], "material_map": [{"Item": "IN1", "Item text": "the carrier codes differ by one character in twelve", "Where the participant meets it": "Pack document D1", "Quoted text": "differ by one character in twelve between the two highest volume carriers"}, {"Item": "IN2", "Item text": "the bay with two of the three errors has dimmer lighting", "Where the participant meets it": "Pack document D1", "Quoted text": "has dimmer lighting than the other bays"}, {"Item": "IN3", "Item text": "the three incident reports name three different workers", "Where the participant meets it": "Pack document D1", "Quoted text": "the three incident reports name three different workers"}, {"Item": "RG1", "Item text": "the dock door scan matches label to truck on every load where it is used", "Where the participant meets it": "Pack document D1", "Quoted text": "the center''s scan at the dock door matches the label to the truck on every load where it is used"}], "source_sheet": {"d9_situation_class": "SC-D9-2", "workplace_demand": "Investigating a repeated loading error with an existing explanation already on record.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where.", "irrelevant_conduct": "Whether the workers were careless; the shift supervisor''s report, as a judgment; who is answerable, which is D2''s.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "That the shift supervisor or any worker was careless or right; anything about the honesty of the reports, which is D1''s; anything about the participant''s seven months in the role.", "compatibility_class": "S3-ASYNC-SUBMISSION", "situation_shown": "In the brief: \"the dispatch labels print carrier codes that differ by one character in twelve.\"", "current_approach": "The incident reports'' account of the errors, and the dock door scan used on some loads.", "indications": [{"id": "IN1", "text": "the carrier codes differ by one character in twelve"}, {"id": "IN2", "text": "the bay with two of the three errors has dimmer lighting"}, {"id": "IN3", "text": "the three incident reports name three different workers"}], "approach_changes": [{"id": "AC1", "text": "change the label format so the two carrier codes differ visibly"}, {"id": "AC2", "text": "raise the lighting in the dimmer bay"}, {"id": "AC3", "text": "use the dock door scan on every outbound load"}], "retention_grounds": [{"id": "RG1", "text": "the dock door scan matches label to truck on every load where it is used"}], "knowledge_sources": [{"id": "KS1", "text": "the warehouse management system''s configuration settings"}, {"id": "KS2", "text": "the three incident reports"}, {"id": "KS3", "text": "the shift supervisor"}, {"id": "KS4", "text": "the loading dock crews"}], "open_points": [{"id": "OP1", "text": "why the dock door scan is not used on every load"}, {"id": "OP2", "text": "whether the errors cluster on one shift"}], "trial_steps": [{"id": "TS1", "text": "change the label format on one carrier''s loads for two weeks before changing it for all"}], "next_work": [{"id": "NW1", "text": "the investigation summary for the director"}, {"id": "NW2", "text": "outbound loading at the center from next week"}], "record_place": "The center''s corrective action register.", "practice_origin": null, "list_note": null, "source_note": "Shared Stage 3 project DEMO-14, which also names D1 and D3 among its primary dimensions; one served instance, a separate observation record in each dimension.", "situation_class_label": "A result showing the current approach is not producing what the work needs", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D9-S3-005", "stage_code": "S3", "source_version_hash": "0b5a512edbfd6314afd893ea8e2cc57aa418fedd452cc07c04f32a36d91c4349", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S3-005' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S3-006', 'source'::public.t3a_content_family, 'SOMETHING VISUAL FOR WEDNESDAY''S VISIT', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "SOMETHING VISUAL FOR WEDNESDAY''S VISIT", "source_digest": "9cdd9a3aa4239eec84568161c44feae0c7ee5b2d3a236c8e5b407bf6439ec355", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are a client services coordinator at a consulting firm, supporting a project to redesign a municipal housing authority''s tenant complaint process. At 4:45 PM Friday the client''s director of tenant services writes that a senior provincial official visits their office next Wednesday and asks for something visual and clear by Tuesday showing the project''s work. Your practice lead is in a workshop all Monday and has asked you to use your judgment and not to overstate where the project is. What the record shows: the request names no format, length or audience detail; a process mapping workshop is complete; the current state analysis is eighty percent done; two pilot design options are drafted but have not been shown to the client; no client facing progress summary exists; and the firm''s client update template has carried every progress report on this project."}], "submission_instructions": "Produce a reply to the client confirming how you read the request and what you propose to deliver; an outline of the document you would produce, with what it includes and leaves out and why; and a note to your practice lead with the request, your approach and what you need from her before Tuesday. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "NOT SERVED", "basis": "The asynchronous form puts no earlier statement back to the participant"}], "material_map": [{"Item": "IN1", "Item text": "the request names no format, length or audience detail", "Where the participant meets it": "Pack document D1", "Quoted text": "the request names no format, length or audience detail"}, {"Item": "IN2", "Item text": "the two pilot design options have not been shown to the client", "Where the participant meets it": "Pack document D1", "Quoted text": "two pilot design options are drafted but have not been shown to the client"}, {"Item": "RG1", "Item text": "the client update template has carried every progress report on this project", "Where the participant meets it": "Pack document D1", "Quoted text": "the firm''s client update template has carried every progress report on this project"}], "source_sheet": {"d9_situation_class": "SC-D9-6", "workplace_demand": "Producing a progress document for a senior visitor from an open request.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where.", "irrelevant_conduct": "The visitor''s role and politics; the client''s habit of late requests; the firm''s relationship with the client.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "That the participant reads ambiguity well or badly; anything about message quality, which is D4''s; that adapting or keeping the template shows creativity or rigidity.", "compatibility_class": "S3-ASYNC-SUBMISSION", "situation_shown": "In the brief: \"the request names no format, length or audience detail.\"", "current_approach": "Reporting progress through the firm''s client update template.", "indications": [{"id": "IN1", "text": "the request names no format, length or audience detail"}, {"id": "IN2", "text": "the two pilot design options have not been shown to the client"}], "approach_changes": [{"id": "AC1", "text": "confirm the format and audience with the client before building"}, {"id": "AC2", "text": "build the summary on the completed workshop and the current state analysis only"}, {"id": "AC3", "text": "adapt the client update template to a one page visual"}], "retention_grounds": [{"id": "RG1", "text": "the client update template has carried every progress report on this project"}], "knowledge_sources": [{"id": "KS1", "text": "the client''s director of tenant services"}, {"id": "KS2", "text": "the practice lead, by a note before Tuesday"}, {"id": "KS3", "text": "the workshop outputs and the current state analysis"}], "open_points": [{"id": "OP1", "text": "who will see the document at the visit"}, {"id": "OP2", "text": "whether the pilot options can be mentioned before the client has seen them"}], "trial_steps": [{"id": "TS1", "text": "send the client a one page outline on Monday before building the full document"}], "next_work": [{"id": "NW1", "text": "the document due Tuesday"}, {"id": "NW2", "text": "Wednesday''s visit"}], "record_place": "The project''s client correspondence file.", "practice_origin": null, "list_note": null, "source_note": "Shared Stage 3 project DEMO-17, which also names D4 and D3 among its primary dimensions; one served instance, a separate observation record in each dimension.", "situation_class_label": "Knowledge the work depends on, undocumented or held only by others", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D9-S3-006", "stage_code": "S3", "source_version_hash": "9cdd9a3aa4239eec84568161c44feae0c7ee5b2d3a236c8e5b407bf6439ec355", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S3-006' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S3-007', 'source'::public.t3a_content_family, 'FOURTEEN OF TWENTY FOUR COMPLETED', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "FOURTEEN OF TWENTY FOUR COMPLETED", "source_digest": "a9f01029097738b55107abd2aea44a7d313e16e33fb5946b5fb8f13bf16e0368", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are a training coordinator at a non profit that delivers professional development to early career teachers. The first cohort of a new twelve week classroom leadership program has finished. What the record shows: fourteen of twenty four participants completed it; satisfaction averaged 2.8 out of 5.0 against a target of 4.0; written feedback called the content too theoretical and the schedule unworkable; sessions ran on Thursday afternoons, when many schools hold weekly staff meetings; the curriculum was written without input from teachers currently in classrooms; a comparable program run by another provider holds its sessions on Saturday mornings and uses practicing teachers as facilitators; and the program''s peer observation component was rated the most useful part by every participant who completed it. Your director wants a report by Friday and the second cohort starts in September."}], "submission_instructions": "Produce an analysis of what the first cohort''s results show; a proposal for the second cohort setting out what you would keep, change and add; and a checklist of actions before September with holders and dates. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out three indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists four sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "NOT SERVED", "basis": "The asynchronous form puts no earlier statement back to the participant"}], "material_map": [{"Item": "IN1", "Item text": "sessions ran on Thursday afternoons, when many schools hold staff meetings", "Where the participant meets it": "Pack document D1", "Quoted text": "sessions ran on Thursday afternoons, when many schools hold weekly staff meetings"}, {"Item": "IN2", "Item text": "written feedback called the content too theoretical", "Where the participant meets it": "Pack document D1", "Quoted text": "written feedback called the content too theoretical"}, {"Item": "IN3", "Item text": "the curriculum was written without input from teachers in classrooms", "Where the participant meets it": "Pack document D1", "Quoted text": "the curriculum was written without input from teachers currently in classrooms"}, {"Item": "RG1", "Item text": "the peer observation component was rated the most useful part", "Where the participant meets it": "Pack document D1", "Quoted text": "the program''s peer observation component was rated the most useful part by every participant who completed it"}], "source_sheet": {"d9_situation_class": "SC-D9-2", "workplace_demand": "Analyzing a program''s first cohort results and proposing what changes for the second.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where.", "irrelevant_conduct": "The director''s sponsorship of the program; the curriculum writer; who is answerable, which is D2''s.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "Anything about the age, career stage or background of the curriculum writer or facilitators; that the other provider''s model is better; how the participant bore the results, which is D8''s boundary.", "compatibility_class": "S3-ASYNC-SUBMISSION", "situation_shown": "In the brief: \"fourteen of twenty four participants completed it.\"", "current_approach": "The first cohort''s design: Thursday afternoon sessions, the existing curriculum and the peer observation component.", "indications": [{"id": "IN1", "text": "sessions ran on Thursday afternoons, when many schools hold staff meetings"}, {"id": "IN2", "text": "written feedback called the content too theoretical"}, {"id": "IN3", "text": "the curriculum was written without input from teachers in classrooms"}], "approach_changes": [{"id": "AC1", "text": "move the sessions off Thursday afternoons"}, {"id": "AC2", "text": "bring practicing teachers into the curriculum and the facilitation"}, {"id": "AC3", "text": "compare the second cohort''s design with the other provider''s program"}], "retention_grounds": [{"id": "RG1", "text": "the peer observation component was rated the most useful part"}], "knowledge_sources": [{"id": "KS1", "text": "the participants who did not complete the program"}, {"id": "KS2", "text": "the other provider''s program"}, {"id": "KS3", "text": "the cohort''s written feedback"}, {"id": "KS4", "text": "the director"}], "open_points": [{"id": "OP1", "text": "which schedule the partner schools can hold"}, {"id": "OP2", "text": "which parts of the curriculum participants found practical"}], "trial_steps": [{"id": "TS1", "text": "run two redesigned sessions with a small group before the September cohort"}], "next_work": [{"id": "NW1", "text": "Friday''s report to the director"}, {"id": "NW2", "text": "the second cohort in September"}], "record_place": "The program''s design record.", "practice_origin": null, "list_note": null, "source_note": "Shared Stage 3 project DEMO-20, also served as SRC-D8-S3-008; one served instance, a separate observation record in each dimension.", "situation_class_label": "A result showing the current approach is not producing what the work needs", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D9-S3-007", "stage_code": "S3", "source_version_hash": "a9f01029097738b55107abd2aea44a7d313e16e33fb5946b5fb8f13bf16e0368", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S3-007' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S4-001', 'source'::public.t3a_content_family, 'THE REPORTING PLATFORM LIVE ON MONDAY', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE REPORTING PLATFORM LIVE ON MONDAY", "source_digest": "e3b9769878943365a8030977e5ed3d23ae1f52ad3d2e7b7177fc290af1a2d9cd", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator records only what was said about the approach to the work: nothing about any person in the room is recordable, including how readily anyone took in what was new. The co-participants are role players; nothing they say is recorded, and nothing they say designates an indication, a change, a ground, a source of knowledge, an open point, a trial step or an item of work.", "participant_pre_brief": "You are on the strategy team of a marketing agency. Leadership has replaced the manual campaign reporting process with an analytics platform that generates client reports, audience models and test recommendations. Training was one two hour session last Friday, and from Monday every client report must come from the platform. What the record shows: half the team could not follow the training session; the documentation is a ninety page manual with no quick start guide; a test report generated yesterday showed a client''s conversion rate at twice the figure in the client''s own analytics; the vendor runs an open help session every Thursday; the old manual reports reconciled to the client''s analytics every month this year; and your manager has asked the team to train each other before Monday.", "script": [{"beat": "B1", "type": "SAY", "spoken": "The platform goes live Monday. I will go round in this order — the account lead, the analyst, the trainer''s contact, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What does this tell you about the work, and what, if anything, do you change or keep in how you do it?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Who or what are we going to, what would we ask, and would we try anything out first?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "Which work does the approach apply to, from when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so we have it right — you said the test report matched the client''s analytics. Did it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As the account lead, state that client reports are due through the new platform from Monday."}, {"Co-participant": "CP-2", "Position stated at the round": "As the analyst, state that half the team could not follow the training session."}, {"Co-participant": "CP-3", "Position stated at the round": "As the trainer''s contact, state that the documentation is a ninety page manual with no quick start guide."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "a test report showed a conversion rate at twice the client''s own figure", "Where the participant meets it": "The pre-brief", "Quoted text": "showed a client''s conversion rate at twice the figure in the client''s own analytics"}, {"Item": "IN2", "Item text": "half the team could not follow the training session", "Where the participant meets it": "The pre-brief", "Quoted text": "half the team could not follow the training session"}, {"Item": "RG1", "Item text": "the manual reports reconciled to the client''s analytics every month this year", "Where the participant meets it": "The pre-brief", "Quoted text": "the old manual reports reconciled to the client''s analytics every month this year"}], "source_sheet": {"d9_situation_class": "SC-D9-3", "workplace_demand": "Preparing a team to use a new reporting platform in three days after limited training.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "Leadership''s decision to switch; the trainer; who could not follow the training.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That anyone on the team is slow with technology; that checking the platform shows distrust; anything about age or technical background.", "compatibility_class": "S4-GROUP-ROUND", "situation_shown": "In the pre-brief: \"a test report generated yesterday showed a client''s conversion rate at twice the figure in the client''s own analytics.\"", "current_approach": "Manual campaign reports reconciled monthly to each client''s analytics.", "indications": [{"id": "IN1", "text": "a test report showed a conversion rate at twice the client''s own figure"}, {"id": "IN2", "text": "half the team could not follow the training session"}], "approach_changes": [{"id": "AC1", "text": "check each platform report against the client''s analytics before it is sent"}, {"id": "AC2", "text": "set up peer sessions on the report steps before Monday"}, {"id": "AC3", "text": "write a one page quick start from the manual"}], "retention_grounds": [{"id": "RG1", "text": "the manual reports reconciled to the client''s analytics every month this year"}], "knowledge_sources": [{"id": "KS1", "text": "the vendor''s weekly help session"}, {"id": "KS2", "text": "the ninety page manual"}, {"id": "KS3", "text": "the colleagues who followed the training"}], "open_points": [{"id": "OP1", "text": "why the test report''s conversion rate differs from the client''s figure"}, {"id": "OP2", "text": "which report steps the team could not follow"}], "trial_steps": [{"id": "TS1", "text": "run one client''s report through the platform alongside the manual version before switching every client"}], "next_work": [{"id": "NW1", "text": "Monday''s client reports"}, {"id": "NW2", "text": "the peer training before Monday"}], "record_place": "The team''s reporting procedure.", "practice_origin": null, "account_test_point": "B6", "account_test_record": "The situation records that the test report''s conversion rate was twice the client''s own figure.", "list_note": null, "source_note": null, "situation_class_label": "A tool or system not used before, now required for the work", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D9-S4-001", "stage_code": "S4", "source_version_hash": "e3b9769878943365a8030977e5ed3d23ae1f52ad3d2e7b7177fc290af1a2d9cd", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S4-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S4-002', 'source'::public.t3a_content_family, 'THE CODE REVIEW TOOL SAID LOW RISK', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE CODE REVIEW TOOL SAID LOW RISK", "source_digest": "8ffd34150454c4e047476735b12d9e73ca60d11a6cb0f8387f1b471723210d5c", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator records only what was said about the approach to the work: nothing about any person in the room is recordable, including how readily anyone took in what was new. The co-participants are role players; nothing they say is recorded, and nothing they say designates an indication, a change, a ground, a source of knowledge, an open point, a trial step or an item of work.", "participant_pre_brief": "You are on the engineering team of a software company providing cloud infrastructure tools. Three days ago a deployment caused a four hour outage that reached 340 clients. A code change passed every automated test but failed under production load. What the record shows: the code review tool the team adopted six months ago rated the change low risk; the deploying engineer read the rating as clearance to skip the manual load test; the load test would have caught the failure; the team''s deployment procedure does not say what a low risk rating permits; the tool has caught four defects that manual review missed in the six months; and the engineering director has asked the team to run a blameless review and produce recommendations.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We are here for the review of the outage. I will go round in this order — the lead, site reliability, the director''s delegate, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What does this tell you about the work, and what, if anything, do you change or keep in how you do it?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Who or what are we going to, what would we ask, and would we try anything out first?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "Which work does the approach apply to, from when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so we have it right — you said the procedure says low risk changes skip the load test. Does it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As the deploying engineer''s lead, state that the change passed every automated test."}, {"Co-participant": "CP-2", "Position stated at the round": "As the site reliability engineer, state that the outage lasted four hours and reached 340 clients."}, {"Co-participant": "CP-3", "Position stated at the round": "As the director''s delegate, state that the review is blameless and asks for recommendations."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out three indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the code review tool rated the change low risk", "Where the participant meets it": "The pre-brief", "Quoted text": "rated the change low risk"}, {"Item": "IN2", "Item text": "the manual load test would have caught the failure", "Where the participant meets it": "The pre-brief", "Quoted text": "the load test would have caught the failure"}, {"Item": "IN3", "Item text": "the procedure does not say what a low risk rating permits", "Where the participant meets it": "The pre-brief", "Quoted text": "the team''s deployment procedure does not say what a low risk rating permits"}, {"Item": "RG1", "Item text": "the tool has caught four defects that manual review missed", "Where the participant meets it": "The pre-brief", "Quoted text": "the tool has caught four defects that manual review missed in the six months"}], "source_sheet": {"d9_situation_class": "SC-D9-2 with SC-D9-3", "workplace_demand": "Recommending the place of an automated review tool in deployment after an outage.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "Who is answerable for the outage, which is D2''s; the deploying engineer; the cost of the credits.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the team trusted the tool too much or too little; that anyone was careless; anything about the participant''s technical ability.", "compatibility_class": "S4-GROUP-ROUND", "situation_shown": "In the pre-brief: \"the deploying engineer read the rating as clearance to skip the manual load test.\"", "current_approach": "Deploying on the code review tool''s rating with the manual load test treated as optional.", "indications": [{"id": "IN1", "text": "the code review tool rated the change low risk"}, {"id": "IN2", "text": "the manual load test would have caught the failure"}, {"id": "IN3", "text": "the procedure does not say what a low risk rating permits"}], "approach_changes": [{"id": "AC1", "text": "require the load test on every production change whatever the tool''s rating"}, {"id": "AC2", "text": "write into the procedure what each rating permits"}, {"id": "AC3", "text": "add a production load profile to the automated tests"}], "retention_grounds": [{"id": "RG1", "text": "the tool has caught four defects that manual review missed"}], "knowledge_sources": [{"id": "KS1", "text": "the code review tool''s rating documentation"}, {"id": "KS2", "text": "the deployment procedure"}, {"id": "KS3", "text": "the site reliability engineer''s outage record"}], "open_points": [{"id": "OP1", "text": "what the tool''s low risk rating is based on"}, {"id": "OP2", "text": "which changes the load test has caught before"}], "trial_steps": [{"id": "TS1", "text": "run the revised procedure on the next two releases before adopting it across teams"}], "next_work": [{"id": "NW1", "text": "the next production deployment"}, {"id": "NW2", "text": "the review''s recommendations"}], "record_place": "The deployment procedure.", "practice_origin": null, "account_test_point": "B6", "account_test_record": "The situation records that the deployment procedure does not say what a low risk rating permits.", "list_note": null, "source_note": null, "situation_class_label": "A result showing the current approach is not producing what the work needs", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D9-S4-002", "stage_code": "S4", "source_version_hash": "8ffd34150454c4e047476735b12d9e73ca60d11a6cb0f8387f1b471723210d5c", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S4-002' and family = 'source'::public.t3a_content_family;
