ull, "account_test_point": "B6", "account_test_record": "The situation records that current packaging lacks the new mandatory health warning.", "list_note": null, "source_note": null, "situation_class_label": "A rule or procedure not used before, now required for the work", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D9-S4-003", "stage_code": "S4", "source_version_hash": "822cbd0823c128cc7c09c159e31438526fb9e21d29e783a10e8875eb8d9767da", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S4-003' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S4-004', 'source'::public.t3a_content_family, 'THE ONLY OPERATOR WHO SETS UP THE MACHINE', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE ONLY OPERATOR WHO SETS UP THE MACHINE", "source_digest": "b63c9297562a91fe947830cd1c92e9b016dc3b4157c9f679cc7d27e00b0db19e", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator records only what was said about the approach to the work: nothing about any person in the room is recordable, including how readily anyone took in what was new. The co-participants are role players; nothing they say is recorded, and nothing they say designates an indication, a change, a ground, a source of knowledge, an open point, a trial step or an item of work.", "participant_pre_brief": "You are on the production team of an injection molding company. One senior operator is the only person who sets up and calibrates the company''s oldest molding machine, which makes medical grade parts for three hospital supply clients. The senior operator leaves the company in sixty days and is willing to train a replacement. What the record shows: three earlier attempts to train another operator did not produce a setup that met the quality standard; the senior operator sets the machine by sound, vibration and sight rather than written steps; the company''s new monitoring system can record sensor data while the machine runs but is not yet configured for this machine; the quality lead''s inspection plan has kept every shipment to the hospital clients within specification; and the operations manager wants a knowledge transfer plan this week.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We need a plan for the machine. I will go round in this order — operations, the senior operator, quality, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What does this tell you about the work, and what, if anything, do you change or keep in how you do it?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Who or what are we going to, what would we ask, and would we try anything out first?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "Which work does the approach apply to, from when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so we have it right — you said the setup steps are already written down. Are they?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As the operations manager, state that the machine must run without the senior operator in sixty days."}, {"Co-participant": "CP-2", "Position stated at the round": "As the senior operator, state that you set the machine by its sound and vibration and are willing to train someone."}, {"Co-participant": "CP-3", "Position stated at the round": "As the quality lead, state that the three hospital clients require medical grade output."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out three items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "three earlier training attempts did not produce a setup that met the standard", "Where the participant meets it": "The pre-brief", "Quoted text": "three earlier attempts to train another operator did not produce a setup that met the quality standard"}, {"Item": "IN2", "Item text": "the setup is done by sound, vibration and sight rather than written steps", "Where the participant meets it": "The pre-brief", "Quoted text": "sets the machine by sound, vibration and sight rather than written steps"}, {"Item": "RG1", "Item text": "the quality lead''s inspection plan has kept every shipment within specification", "Where the participant meets it": "The pre-brief", "Quoted text": "the quality lead''s inspection plan has kept every shipment to the hospital clients within specification"}], "source_sheet": {"d9_situation_class": "SC-D9-5 with SC-D9-6", "workplace_demand": "Planning how another operator learns an undocumented machine setup within sixty days.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The senior operator''s reasons for leaving; the senior operator''s age or tenure; the earlier trainees.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "Anything about the age, tenure or learning of the senior operator or any trainee; that tacit skill is better or worse than written steps.", "compatibility_class": "S4-GROUP-ROUND", "situation_shown": "In the pre-brief: \"sets the machine by sound, vibration and sight rather than written steps.\"", "current_approach": "Setup and calibration by the senior operator alone, with the quality lead''s inspection plan.", "indications": [{"id": "IN1", "text": "three earlier training attempts did not produce a setup that met the standard"}, {"id": "IN2", "text": "the setup is done by sound, vibration and sight rather than written steps"}], "approach_changes": [{"id": "AC1", "text": "configure the monitoring system to record the senior operator''s setups"}, {"id": "AC2", "text": "write the setup steps from recorded sessions with the senior operator"}, {"id": "AC3", "text": "pair a trainee with the senior operator on every setup from now"}], "retention_grounds": [{"id": "RG1", "text": "the quality lead''s inspection plan has kept every shipment within specification"}], "knowledge_sources": [{"id": "KS1", "text": "the senior operator"}, {"id": "KS2", "text": "the monitoring system''s sensor data"}, {"id": "KS3", "text": "the quality lead''s inspection records"}], "open_points": [{"id": "OP1", "text": "what the senior operator listens and feels for at each setup step"}, {"id": "OP2", "text": "which setups the earlier attempts could not reproduce"}], "trial_steps": [{"id": "TS1", "text": "have the trainee run one setup under the senior operator''s watch and inspect the output before relying on it"}], "next_work": [{"id": "NW1", "text": "the knowledge transfer plan this week"}, {"id": "NW2", "text": "the sixty days before the senior operator leaves"}, {"id": "NW3", "text": "the hospital clients'' next orders"}], "record_place": "The machine''s setup procedure file.", "practice_origin": null, "account_test_point": "B6", "account_test_record": "The situation records that the setup steps are not written down.", "list_note": null, "source_note": null, "situation_class_label": "Another person''s method for the work available to the participant", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D9-S4-004", "stage_code": "S4", "source_version_hash": "b63c9297562a91fe947830cd1c92e9b016dc3b4157c9f679cc7d27e00b0db19e", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S4-004' and family = 'source'::public.t3a_content_family;
