  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "FOURTEEN DAYS TO A NEW MARKET PLAN", "source_digest": "f1143ffb45fafa186a93b2c2cf70141cf77283e0501784a2adec0985a235b55f", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator records only what was said about the approach to the work: nothing about any person in the room is recordable, including how readily anyone took in what was new. The co-participants are role players; nothing they say is recorded, and nothing they say designates an indication, a change, a ground, a source of knowledge, an open point, a trial step or an item of work.", "participant_pre_brief": "You are on the business development team of a specialty food producer that exports organic grain products to three markets. The chief executive has returned from a trade mission with a possible exclusive distribution deal in a market abroad where the company has not operated. The distributor wants a decision and a preliminary plan within fourteen days. What the record shows: the company''s market intelligence platform produced a regulatory summary for the market; the summary cites a labeling rule two years out of date; the trade commissioner''s office publishes current import requirements; an exporter in the same trade association has sold into the market for four years; the company''s market entry checklist, used in all three current markets, starts with a regulatory review by outside counsel; and none of the team has worked in this market.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We have fourteen days. I will go round in this order — the chief executive''s delegate, regulatory, the distributor liaison, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What does this tell you about the work, and what, if anything, do you change or keep in how you do it?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Who or what are we going to, what would we ask, and would we try anything out first?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "Which work does the approach apply to, from when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so we have it right — you said the platform''s summary is current. Is it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As the chief executive''s delegate, state that the distributor wants a decision within fourteen days."}, {"Co-participant": "CP-2", "Position stated at the round": "As the regulatory specialist, state that the market''s import rules differ from the company''s current markets."}, {"Co-participant": "CP-3", "Position stated at the round": "As the distributor liaison, state that the distributor asks for exclusive rights across the region."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists four sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the platform''s summary cites a labeling rule two years out of date", "Where the participant meets it": "The pre-brief", "Quoted text": "the summary cites a labeling rule two years out of date"}, {"Item": "IN2", "Item text": "the deal is for exclusive distribution in a market new to the company", "Where the participant meets it": "The pre-brief", "Quoted text": "a possible exclusive distribution deal"}, {"Item": "RG1", "Item text": "the market entry checklist starts with a regulatory review by outside counsel", "Where the participant meets it": "The pre-brief", "Quoted text": "the company''s market entry checklist, used in all three current markets, starts with a regulatory review by outside counsel"}], "source_sheet": {"d9_situation_class": "SC-D9-4", "workplace_demand": "Preparing a decision and plan on a market new to the company in fourteen days.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The market''s culture or customs; the distributor''s reputation; the revenue estimate.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "Any ranking of the market''s business practice against the company''s own; anything about the team''s experience as a limit; that using the platform shows reliance.", "compatibility_class": "S4-GROUP-ROUND", "situation_shown": "In the pre-brief: \"the summary cites a labeling rule two years out of date.\"", "current_approach": "The company''s market entry checklist, starting with a regulatory review by outside counsel.", "indications": [{"id": "IN1", "text": "the platform''s summary cites a labeling rule two years out of date"}, {"id": "IN2", "text": "the deal is for exclusive distribution in a market new to the company"}], "approach_changes": [{"id": "AC1", "text": "check the platform''s summary against the trade commissioner''s current requirements"}, {"id": "AC2", "text": "speak with the exporter who has sold into the market"}, {"id": "AC3", "text": "ask the distributor for a nonexclusive first year"}], "retention_grounds": [{"id": "RG1", "text": "the market entry checklist starts with a regulatory review by outside counsel"}], "knowledge_sources": [{"id": "KS1", "text": "the trade commissioner''s office"}, {"id": "KS2", "text": "the exporter in the trade association"}, {"id": "KS3", "text": "the market intelligence platform"}, {"id": "KS4", "text": "outside counsel"}], "open_points": [{"id": "OP1", "text": "which import requirements apply to organic grain products"}, {"id": "OP2", "text": "what exclusive rights across the region would commit the company to"}], "trial_steps": [{"id": "TS1", "text": "ship one product line through the distributor before granting rights to the full range"}], "next_work": [{"id": "NW1", "text": "the decision and plan within fourteen days"}, {"id": "NW2", "text": "the first shipments if the deal goes ahead"}], "record_place": "The market entry file.", "practice_origin": null, "account_test_point": "B6", "account_test_record": "The situation records that the platform''s summary cites a labeling rule two years out of date.", "list_note": null, "source_note": null, "situation_class_label": "Work outside the work the participant has done before", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D9-S4-005", "stage_code": "S4", "source_version_hash": "f1143ffb45fafa186a93b2c2cf70141cf77283e0501784a2adec0985a235b55f", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S4-005' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S4-006', 'source'::public.t3a_content_family, 'SIX HOURS IN AND THE MODEL MISCLASSIFIES', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "SIX HOURS IN AND THE MODEL MISCLASSIFIES", "source_digest": "3c546f126e70b7a1385010c5519d2108d56d688c6da231b238f946a88901c385", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator records only what was said about the approach to the work: nothing about any person in the room is recordable, including how readily anyone took in what was new. The co-participants are role players; nothing they say is recorded, and nothing they say designates an indication, a change, a ground, a source of knowledge, an open point, a trial step or an item of work.", "participant_pre_brief": "You are on a team in a forty eight hour internal hackathon at a financial services company. The challenge is a prototype that cuts customer onboarding from twelve days to under forty eight hours. Your team chose a document verification and identity matching tool. Six hours in, the prototype is not working. What the record shows: the model misclassifies about a third of test documents; most misclassified documents are utility bills; the model classifies passports and licenses correctly; the hackathon mentor advises narrowing to one document type; the user interface is incomplete; the challenge brief scores working prototypes on the onboarding step they shorten; and eighteen hours remain.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Eighteen hours left. I will go round in this order — the mentor, the developer, the designer, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What does this tell you about the work, and what, if anything, do you change or keep in how you do it?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Who or what are we going to, what would we ask, and would we try anything out first?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "Which work does the approach apply to, from when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so we have it right — you said the model fails on passports. Does it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As the hackathon mentor, state that you advise the team to narrow the prototype to one document type."}, {"Co-participant": "CP-2", "Position stated at the round": "As the developer, state that the model misclassifies documents."}, {"Co-participant": "CP-3", "Position stated at the round": "As the designer, state that the user interface is incomplete."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the model misclassifies about a third of test documents", "Where the participant meets it": "The pre-brief", "Quoted text": "the model misclassifies about a third of test documents"}, {"Item": "IN2", "Item text": "most misclassified documents are utility bills", "Where the participant meets it": "The pre-brief", "Quoted text": "most misclassified documents are utility bills"}, {"Item": "RG1", "Item text": "the model classifies passports and licenses correctly", "Where the participant meets it": "The pre-brief", "Quoted text": "the model classifies passports and licenses correctly"}], "source_sheet": {"d9_situation_class": "SC-D9-2 with SC-D9-7", "workplace_demand": "Deciding whether to narrow or continue a failing prototype with limited time.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "Winning the hackathon; the investors on the panel; the team''s disagreement as a conflict, which is D5''s.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That pivoting or persisting is the better choice; that following the mentor shows deference; anything about the participant''s technical skill.", "compatibility_class": "S4-GROUP-ROUND", "situation_shown": "In the pre-brief: \"the model misclassifies about a third of test documents.\"", "current_approach": "A document verification prototype covering every document type.", "indications": [{"id": "IN1", "text": "the model misclassifies about a third of test documents"}, {"id": "IN2", "text": "most misclassified documents are utility bills"}], "approach_changes": [{"id": "AC1", "text": "narrow the prototype to identity documents, as the mentor advises"}, {"id": "AC2", "text": "drop utility bills from the prototype''s scope"}, {"id": "AC3", "text": "finish the user interface before further model work"}], "retention_grounds": [{"id": "RG1", "text": "the model classifies passports and licenses correctly"}], "knowledge_sources": [{"id": "KS1", "text": "the hackathon mentor"}, {"id": "KS2", "text": "the challenge brief"}, {"id": "KS3", "text": "the test document set"}], "open_points": [{"id": "OP1", "text": "why utility bills are misclassified"}, {"id": "OP2", "text": "which onboarding step the narrowed prototype shortens"}], "trial_steps": [{"id": "TS1", "text": "run the narrowed model on a fresh test set before rebuilding the interface around it"}], "next_work": [{"id": "NW1", "text": "the next eighteen hours of the hackathon"}, {"id": "NW2", "text": "the presentation to the judging panel"}], "record_place": "The team''s build notes.", "practice_origin": null, "account_test_point": "B6", "account_test_record": "The situation records that the model classifies passports and licenses correctly.", "list_note": null, "source_note": null, "situation_class_label": "A result showing the current approach is not producing what the work needs", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D9-S4-006", "stage_code": "S4", "source_version_hash": "3c546f126e70b7a1385010c5519d2108d56d688c6da231b238f946a88901c385", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S4-006' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S4-007', 'source'::public.t3a_content_family, 'THE CONTRACT THE COMPETITOR WON', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE CONTRACT THE COMPETITOR WON", "source_digest": "f96426db9c43c6182a3e59ea3eea341048bd5832fbcf630484b2efa8c9775ca4", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator records only what was said about the approach to the work: nothing about any person in the room is recordable, including how readily anyone took in what was new. The co-participants are role players; nothing they say is recorded, and nothing they say designates an indication, a change, a ground, a source of knowledge, an open point, a trial step or an item of work.", "participant_pre_brief": "You are on the product strategy team of a telecommunications company serving businesses. A competitor has won a three year, $14 million contract with a logistics company your team pursued for eight months. What the record shows: the client''s debrief call said the competitor''s proposal included a ninety day implementation plan with named milestones, and yours did not; the client''s request for proposals asked for an implementation approach in one line; the competitor''s public case studies describe the same implementation format in three earlier wins; your proposal''s network and price sections scored above the competitor''s, the client said; the company''s competitive intelligence tool tracks competitor announcements; and the vice president wants a set of changes for future bids.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We lost the contract. I will go round in this order — sales, the bid manager, the note taker, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What does this tell you about the work, and what, if anything, do you change or keep in how you do it?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Who or what are we going to, what would we ask, and would we try anything out first?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "Which work does the approach apply to, from when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so we have it right — you said the request for proposals did not ask about implementation. Did it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As the vice president of sales, state that the company had the better network and price and still lost."}, {"Co-participant": "CP-2", "Position stated at the round": "As the bid manager, state that the proposal followed the request for proposals section by section."}, {"Co-participant": "CP-3", "Position stated at the round": "As the note taker, state that the client''s debrief mentioned the competitor''s implementation plan."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists four sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the competitor''s proposal included a ninety day implementation plan with named milestones", "Where the participant meets it": "The pre-brief", "Quoted text": "included a ninety day implementation plan with named milestones"}, {"Item": "IN2", "Item text": "the competitor used the same implementation format in three earlier wins", "Where the participant meets it": "The pre-brief", "Quoted text": "describe the same implementation format in three earlier wins"}, {"Item": "RG1", "Item text": "the proposal''s network and price sections scored above the competitor''s", "Where the participant meets it": "The pre-brief", "Quoted text": "your proposal''s network and price sections scored above the competitor''s, the client said"}], "source_sheet": {"d9_situation_class": "SC-D9-5", "workplace_demand": "Working out what to change in future bids after a competitor won a contract.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "Whether the client chose well; the competitor''s company; who is answerable for the loss, which is D2''s.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That copying or not copying the competitor shows humility or pride; anything about the bid team''s ability.", "compatibility_class": "S4-GROUP-ROUND", "situation_shown": "In the pre-brief: \"the competitor''s proposal included a ninety day implementation plan with named milestones.\"", "current_approach": "Proposals built section by section on the request for proposals, led by network and price.", "indications": [{"id": "IN1", "text": "the competitor''s proposal included a ninety day implementation plan with named milestones"}, {"id": "IN2", "text": "the competitor used the same implementation format in three earlier wins"}], "approach_changes": [{"id": "AC1", "text": "add a dated implementation plan to every future proposal"}, {"id": "AC2", "text": "review the request for proposals for one line requirements before each bid"}, {"id": "AC3", "text": "track competitor case studies in the intelligence tool"}], "retention_grounds": [{"id": "RG1", "text": "the proposal''s network and price sections scored above the competitor''s"}], "knowledge_sources": [{"id": "KS1", "text": "the client''s debrief"}, {"id": "KS2", "text": "the competitor''s public case studies"}, {"id": "KS3", "text": "the competitive intelligence tool"}, {"id": "KS4", "text": "the bid manager"}], "open_points": [{"id": "OP1", "text": "how the client weighed implementation against network and price"}, {"id": "OP2", "text": "what the competitor''s milestones covered"}], "trial_steps": [{"id": "TS1", "text": "use the implementation plan format on the next bid and ask that client for feedback on it before making it standard"}], "next_work": [{"id": "NW1", "text": "the changes for future bids"}, {"id": "NW2", "text": "the next bid the team prepares"}], "record_place": "The bid procedure.", "practice_origin": null, "account_test_point": "B6", "account_test_record": "The situation records that the request for proposals asked for an implementation approach in one line.", "list_note": null, "source_note": null, "situation_class_label": "Another person''s method for the work available to the participant", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D9-S4-007", "stage_code": "S4", "source_version_hash": "f96426db9c43c6182a3e59ea3eea341048bd5832fbcf630484b2efa8c9775ca4", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S4-007' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S4-008', 'source'::public.t3a_content_family, 'THE FIRST SUSTAINABILITY REPORT, IN SIX MONTHS', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE FIRST SUSTAINABILITY REPORT, IN SIX MONTHS", "source_digest": "caf53f27e08799670da3cf5004ce093fde6574dd4b2bae659d007d7c8e880144", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator records only what was said about the approach to the work: nothing about any person in the room is recordable, including how readily anyone took in what was new. The co-participants are role players; nothing they say is recorded, and nothing they say designates an indication, a change, a ground, a source of knowledge, an open point, a trial step or an item of work.", "participant_pre_brief": "You are on the finance and sustainability team of an industrial manufacturer. The board has required a first sustainability report within six months, aligned with the international sustainability disclosure framework. None of the team has produced one. What the record shows: the three consulting firms contacted are booked for nine months; the company''s analytics platform has a module that drafts report sections from the framework''s templates, and the module has not been checked against the framework''s current version; forty percent of the data the framework asks for is not collected today; the framework''s standard setter publishes its standards and guidance online; a supplier of the company published its first report last year; and the company''s financial reporting controls, under which every figure is traced to a source record, have passed every audit.", "script": [{"beat": "B1", "type": "SAY", "spoken": "The board wants the report in six months. I will go round in this order — finance, operations data, the board liaison, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What does this tell you about the work, and what, if anything, do you change or keep in how you do it?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Who or what are we going to, what would we ask, and would we try anything out first?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "Which work does the approach apply to, from when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so we have it right — you said the module was checked against the current framework. Was it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As the chief financial officer''s delegate, state that no outside consultant is available for nine months."}, {"Co-participant": "CP-2", "Position stated at the round": "As the operations data lead, state that forty percent of the data the framework asks for is not collected today."}, {"Co-participant": "CP-3", "Position stated at the round": "As the board''s liaison, state that the board wants the first report within six months."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-08", "state": "DIRECT", "basis": "The situation names a place a record could be made"}, {"question": "Q-D9-09", "state": "DIRECT", "basis": "The account test puts an earlier statement back"}], "material_map": [{"Item": "IN1", "Item text": "the drafting module has not been checked against the current framework", "Where the participant meets it": "The pre-brief", "Quoted text": "the module has not been checked against the framework''s current version"}, {"Item": "IN2", "Item text": "forty percent of the data the framework asks for is not collected today", "Where the participant meets it": "The pre-brief", "Quoted text": "forty percent of the data the framework asks for is not collected today"}, {"Item": "RG1", "Item text": "the financial reporting controls trace every figure to a source record", "Where the participant meets it": "The pre-brief", "Quoted text": "under which every figure is traced to a source record, have passed every audit"}], "source_sheet": {"d9_situation_class": "SC-D9-4 with SC-D9-3", "workplace_demand": "Producing a first sustainability report without outside help.", "relevant_conduct": "Which indications of what the situation showed were named; which change to the approach was stated; what was stated about keeping the current approach, and on what ground; which source of knowledge was stated as one to go to; which open point a question was stated about; which trial step was stated; what work ahead was named, and from when; whether a record of the approach was stated, and where; what was stated when an earlier statement was put back.", "irrelevant_conduct": "The board''s decision; the consultants'' availability; the merits of the framework.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the team lacks capacity; that using or not using the module shows reliance or caution; anything about the participant''s background.", "compatibility_class": "S4-GROUP-ROUND", "situation_shown": "In the pre-brief: \"the module has not been checked against the framework''s current version.\"", "current_approach": "Financial reporting under controls that trace every figure to a source record.", "indications": [{"id": "IN1", "text": "the drafting module has not been checked against the current framework"}, {"id": "IN2", "text": "forty percent of the data the framework asks for is not collected today"}], "approach_changes": [{"id": "AC1", "text": "check the module''s draft sections against the published standards"}, {"id": "AC2", "text": "start collecting the missing data with operations"}, {"id": "AC3", "text": "report the first year on the data held, with the gaps stated"}], "retention_grounds": [{"id": "RG1", "text": "the financial reporting controls trace every figure to a source record"}], "knowledge_sources": [{"id": "KS1", "text": "the standard setter''s published standards and guidance"}, {"id": "KS2", "text": "the supplier that published its first report last year"}, {"id": "KS3", "text": "the analytics platform''s drafting module"}], "open_points": [{"id": "OP1", "text": "which disclosures the framework requires in a first year"}, {"id": "OP2", "text": "which of the missing data can be collected within six months"}], "trial_steps": [{"id": "TS1", "text": "draft one section with the module and check it against the standards before using it for the rest"}], "next_work": [{"id": "NW1", "text": "the first report within six months"}, {"id": "NW2", "text": "the data collection that starts now"}], "record_place": "The report''s working file.", "practice_origin": null, "account_test_point": "B6", "account_test_record": "The situation records that the drafting module has not been checked against the framework''s current version.", "list_note": null, "source_note": null, "situation_class_label": "Work outside the work the participant has done before", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D9-S4-008", "stage_code": "S4", "source_version_hash": "caf53f27e08799670da3cf5004ce093fde6574dd4b2bae659d007d7c8e880144", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D9-S4-008' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D9-S4-009', 'source'::public.t3a_content_family, 'THREE NEW HIRES FROM MONDAY', 'D9', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v1.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THREE NEW HIRES FROM MONDAY", "source_digest": "38dc77897881ef99dfbcdb18e04cd8298366a4a5bb03b89115574b2b527981b6", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator records only what was said about the approach to the work: nothing about any person in the room is recordable, including how readily anyone took in what was new. The co-participants are role players; nothing they say is recorded, and nothing they say designates an indication, a change, a ground, a source of knowledge, an open point, a trial step or an item of work.", "participant_pre_brief": "You are on the operations team of a logistics software company with one hundred twenty trucking company accounts. Two client success managers resigned yesterday and a third moves to another team on Monday. Three new hires, due in two weeks for a three week onboarding, now start on Monday. What the record shows: the company''s knowledge base holds product documentation, client playbooks and recorded training, and was last updated two months ago; three product updates have shipped since; the chatbot answers new hires'' product questions from the knowledge base; the two remaining managers know the updates; the standard onboarding''s first module, a client call shadowing day, is rated the most useful part by every past cohort; and the chief executive wants to know the risk level on Monday.", "script": [{"beat": "B1", "type": "SAY", "spoken": "They start Monday. I will go round in this order — the chief executive''s delegate, client success, the knowledge base owner, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What does this tell you about the work, and what, if anything, do you change or keep in how you do it?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "Who or what are we going to, what would we ask, and would we try anything out first?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}, {"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "Which work does the approach apply to, from when, and what goes on the record?", "direction": "Read once, verbatim.", "capture": [{"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so we have it right — you said the knowledge base covers the three updates. Does it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As the chief executive''s delegate, state that the three new hires start on Monday."}, {"Co-participant": "CP-2", "Position stated at the round": "As a client success manager, state that two managers will cover one hundred twenty accounts on Monday."}, {"Co-participant": "CP-3", "Position stated at the round": "As the knowledge base owner, state that the knowledge base was last updated two months ago."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D9-01", "state": "DIRECT", "basis": "The situation sets out two indications"}, {"question": "Q-D9-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-02", "state": "DIRECT", "basis": "The situation lists three changes to the approach"}, {"question": "Q-D9-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-03", "state": "DIRECT", "basis": "The situation records one grounds for keeping the current approach"}, {"question": "Q-D9-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-04", "state": "DIRECT", "basis": "The situation lists three sources of knowledge"}, {"question": "Q-D9-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-05", "state": "DIRECT", "basis": "The situation sets out two open points"}, {"question": "Q-D9-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-06", "state": "DIRECT", "basis": "The situation lists one trial steps"}, {"question": "Q-D9-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D9-07", "state": "DIRECT", "basis": "The situation sets out two items of work ahead"}, {"question": "Q-D9-07b", "state": "CONDITIONAL", "basis": "Served